          .select('*, projects(name), profiles:requested_by(full_name)')
          .in('project_id', projectIds)
          .order('created_at', { ascending: false });

        if (searchQuery) query = query.ilike('item_name', `%${searchQuery}%`);
        const { data, error } = await query;
        if (error && error.code !== '42P01') throw error;
        setRequests(data || []);
      } else {
        // Fetch materials for PM's projects
        let query = supabase
          .from('materials')
          .select('*, projects(name)')
          .in('project_id', projectIds)
          .order('created_at', { ascending: false });
          
        if (searchQuery) query = query.ilike('item_name', `%${searchQuery}%`);
        const { data, error } = await query;
        if (error && error.code !== '42P01') throw error;
        setStockData(data || []);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadRequests();
  }, [searchQuery, activeTab]);

  const handleApprove = async (req: any) => {
    setActioningId(req.id);
    try {
      await supabase.from('material_requests').update({ status: 'Approved' }).eq('id', req.id);
      
      // Notify Supplier
      await supabase.from('notifications').insert({
        project_id: req.project_id,
        target_role: 'Supplier',
        title: 'New Approved Order',
        message: `Project Manager approved ${req.quantity} ${req.unit} of ${req.item_name}. Ready for fulfillment.`,
      });

      // Notify Site Manager
      if (req.requested_by) {
        await supabase.from('notifications').insert({
          target_user_id: req.requested_by,
          title: 'Material Request Approved',
          message: `Your request for ${req.item_name} was approved!`,
        });
      }

      Alert.alert('Approved', 'Request has been forwarded to the Supplier.');
      loadRequests();
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setActioningId(null);
    }
  };

  const handleRejectConfirm = async () => {
    if (!selectedReqId || !rejectReason) {
      Alert.alert('Error', 'Please provide a reason for rejection.');
      return;
    }

    setActioningId(selectedReqId);
    try {
      const req = requests.find(r => r.id === selectedReqId);
      await supabase.from('material_requests').update({ status: 'Rejected', notes: rejectReason }).eq('id', selectedReqId);
      
      if (req?.requested_by) {
        await supabase.from('notifications').insert({
          target_user_id: req.requested_by,
          title: 'Material Request Rejected',
          message: `Your request for ${req.item_name} was rejected. Reason: ${rejectReason}`,
        });
      }

      setShowRejectModal(false);
      setRejectReason('');
      setSelectedReqId(null);
      loadRequests();
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setActioningId(null);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Pending Approval': return 'bg-yellow-100 text-yellow-800';
      case 'Approved': return 'bg-blue-100 text-blue-800';
      case 'Ordered': return 'bg-purple-100 text-purple-800';
      case 'Delivered': return 'bg-green-100 text-green-800';
      case 'Rejected': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title="Materials Management" 
        showAction={false} 
        initialSearchQuery={searchQuery}
        onSearch={setSearchQuery}
      />

      {/* Tabs */}
      <View className="flex-row px-8 mt-6">
        <Pressable 
          onPress={() => setActiveTab('queue')}
          className={`pb-3 mr-8 border-b-2 ${activeTab === 'queue' ? 'border-brand-orange' : 'border-transparent'}`}
        >
          <Text className={`font-bold text-base ${activeTab === 'queue' ? 'text-brand-orange' : 'text-gray-500'}`}>Approval Queue</Text>
        </Pressable>
        <Pressable 
          onPress={() => setActiveTab('stock')}
          className={`pb-3 border-b-2 ${activeTab === 'stock' ? 'border-brand-orange' : 'border-transparent'}`}
        >
          <Text className={`font-bold text-base ${activeTab === 'stock' ? 'text-brand-orange' : 'text-gray-500'}`}>Site Stock</Text>
        </Pressable>
      </View>

      <View className="flex-1 p-8">
        {loading ? (
          <ActivityIndicator size="large" color="#F97316" className="mt-10" />
        ) : (
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 flex-1 overflow-hidden">
            <View className="flex-row py-4 px-6 border-b border-gray-100 bg-gray-50">
              <Text className="w-1/5 text-xs font-bold text-gray-500 uppercase">Item</Text>
              <Text className="w-1/6 text-xs font-bold text-gray-500 uppercase">{activeTab === 'queue' ? 'Project' : 'Site'}</Text>
              <Text className="w-1/6 text-xs font-bold text-gray-500 uppercase">Quantity</Text>
              <Text className="w-1/6 text-xs font-bold text-gray-500 uppercase">{activeTab === 'queue' ? 'Status' : 'Last Updated'}</Text>
              {activeTab === 'queue' && <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase text-right">Actions</Text>}
            </View>

            <ScrollView showsVerticalScrollIndicator={false}>
              {activeTab === 'queue' ? (
                requests.length === 0 ? (
                  <View className="p-10 items-center justify-center">
                    <Ionicons name="checkmark-done-circle-outline" size={48} color="#D1D5DB" />
                    <Text className="text-gray-400 mt-4">No pending requests to approve.</Text>
                  </View>
                ) : (
                  requests.map(req => (
                    <View key={req.id} className="flex-row items-center py-4 px-6 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                      <View className="w-1/5">
                        <Text className="font-bold text-brand-text">{req.item_name}</Text>
                        <Text className="text-xs text-gray-400 mt-1">By: {req.profiles?.full_name || 'Site Manager'}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-gray-500 text-sm truncate">{req.projects?.name || 'Unknown'}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-brand-text font-semibold">{req.quantity} {req.unit}</Text>
                      </View>
                      <View className="w-1/6">
                        <View className={`self-start px-2.5 py-1 rounded-md ${getStatusColor(req.status).split(' ')[0]}`}>
                          <Text className={`text-xs font-bold ${getStatusColor(req.status).split(' ')[1]}`}>{req.status}</Text>
                        </View>
                      </View>
                      <View className="w-1/4 flex-row justify-end space-x-2 gap-2">
                        {req.status === 'Pending Approval' ? (
                          <>
                            <Pressable 
                              onPress={() => {
                                setSelectedReqId(req.id);
                                setShowRejectModal(true);
                              }}
                              disabled={actioningId === req.id}
                              className="bg-white border border-red-200 px-4 py-2 rounded-lg hover:bg-red-50"
                            >
                              <Text className="text-red-600 font-semibold text-xs">Reject</Text>
                            </Pressable>
                            <Pressable 
                              onPress={() => handleApprove(req)}
                              disabled={actioningId === req.id}
                              className="bg-brand-orange px-4 py-2 rounded-lg hover:bg-orange-600 flex-row items-center"
                            >
                              {actioningId === req.id ? (
                                <ActivityIndicator size="small" color="white" />
                              ) : (
                                <Text className="text-white font-semibold text-xs">Approve</Text>
                              )}
                            </Pressable>
                          </>
                        ) : (
                          <Text className="text-gray-400 text-xs italic">{req.notes || 'Processed'}</Text>
                        )}
                      </View>
                    </View>
                  ))
                )
              ) : (
                stockData.length === 0 ? (
                  <View className="p-10 items-center justify-center">
                    <Ionicons name="cube-outline" size={48} color="#D1D5DB" />
                    <Text className="text-gray-400 mt-4">No site stock data found.</Text>
                  </View>
                ) : (
                  stockData.map(stock => (
                    <View key={stock.id} className="flex-row items-center py-4 px-6 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                      <View className="w-1/5">
                        <Text className="font-bold text-brand-text">{stock.item_name}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-gray-500 text-sm truncate">{stock.projects?.name || 'Unknown'}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-brand-text font-semibold">{stock.global_stock_quantity ?? 0} {stock.unit}</Text>
                      </View>
                      <View className="w-1/6">
                        <Text className="text-gray-500 text-xs">
                          {stock.created_at ? new Date(stock.created_at).toLocaleDateString() : '—'}
                        </Text>
                      </View>
                    </View>
                  ))
                )
              )}
            </ScrollView>
          </View>
        )}
      </View>

      {/* Reject Modal */}
      <Modal visible={showRejectModal} transparent animationType="fade">
        <View className="flex-1 bg-black/50 justify-center items-center p-4">
          <View className="bg-white w-full max-w-sm rounded-2xl overflow-hidden shadow-2xl">
            <View className="p-4 border-b border-gray-100 flex-row justify-between items-center bg-gray-50">
              <Text className="text-lg font-bold text-red-600">Reject Request</Text>
              <Pressable onPress={() => !actioningId && setShowRejectModal(false)}>
                <Ionicons name="close" size={24} color="#6B7280" />
              </Pressable>
            </View>
            
            <View className="p-6">
              <Text className="text-sm font-semibold text-gray-700 mb-2">Reason for Rejection</Text>
              <TextInput
                className="border border-gray-200 rounded-xl p-3 text-brand-text bg-gray-50 mb-6"
                placeholder="E.g. Exceeds current budget."
                value={rejectReason}
                onChangeText={setRejectReason}
                multiline
                numberOfLines={3}
              />

              <Pressable 
                onPress={handleRejectConfirm}
                disabled={actioningId !== null || !rejectReason}
                className={`py-3 rounded-xl flex-row items-center justify-center ${actioningId !== null || !rejectReason ? 'bg-red-300' : 'bg-red-600 hover:bg-red-700'}`}
              >
                {actioningId !== null ? (
                  <ActivityIndicator size="small" color="white" />
                ) : (
                  <Text className="text-white font-bold text-sm">Confirm Rejection</Text>
                )}
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>

    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, TextInput } from 'react-native';
import { useRouter, Link } from 'expo-router';
import { supabase } from '../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { useResponsive } from '../../../hooks/useResponsive';
import { formatMoney } from '../../../utils/format';

export default function PMProjectsList() {
  const router = useRouter();
  const [projects, setProjects] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const { isMobile } = useResponsive();

  useEffect(() => {
    let isMounted = true;
    const fetchProjects = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        const user = sessionData?.session?.user;
        if (!user) return;

        let query = supabase.from('projects').select('*').eq('pm_id', user.id).order('created_at', { ascending: false });
        if (search) {
          query = query.ilike('name', `%${search}%`);
        }
        const { data, error } = await query;
        if (error) throw error;
        if (isMounted) setProjects(data || []);
      } catch (err) {
        console.error('Error fetching projects', err);
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    fetchProjects();
    return () => { isMounted = false; };
  }, [search]);

  return (
    <View className="flex-1 bg-gray-50">
      <View className="flex-1 flex-col h-screen overflow-hidden">
        <TopNav title="My Projects" showAction={false} />

        <ScrollView className={`flex-1 ${isMobile ? 'px-4 py-4' : 'px-8 py-6'}`} showsVerticalScrollIndicator={false}>
          <View style={{ flexDirection: isMobile ? 'column' : 'row', justifyContent: isMobile ? 'flex-start' : 'space-between', alignItems: isMobile ? 'flex-start' : 'center', marginBottom: 24, gap: isMobile ? 12 : 0 }}>
            <Text className="text-2xl font-bold text-brand-text">Assigned Projects</Text>

            <View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: '#fff', borderWidth: 1, borderColor: '#E5E7EB', borderRadius: 8, paddingHorizontal: 12, paddingVertical: 8, width: isMobile ? '100%' : 256, shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.05, shadowRadius: 2 }}>
              <Ionicons name="search" size={16} color="#9CA3AF" />
              <TextInput 
                className="flex-1 ml-2 text-sm text-brand-text outline-none"
                placeholder="Search projects..."
                placeholderTextColor="#9CA3AF"
                value={search}
                onChangeText={setSearch}
              />
            </View>
          </View>

          <View className={`bg-white shadow-sm border border-gray-100 min-h-[400px] ${isMobile ? 'rounded-none border-0 bg-transparent shadow-none' : 'rounded-xl p-6'}`}>
            {!isMobile && (
              <View className="flex-row py-3 border-b border-gray-200 pr-2">
                <Text className="w-[30%] text-xs font-semibold text-gray-500 uppercase">Project Name</Text>
                <Text className="w-[20%] text-xs font-semibold text-gray-500 uppercase">Location</Text>
                <Text className="w-[15%] text-xs font-semibold text-gray-500 uppercase">Budget</Text>
                <Text className="w-[15%] text-xs font-semibold text-gray-500 uppercase">Status</Text>
                <Text className="flex-1 text-xs font-semibold text-gray-500 uppercase text-right">Action</Text>
              </View>
            )}

            {loading ? (
              <View className="py-20 items-center justify-center">
                <ActivityIndicator color="#F97316" />
              </View>
            ) : projects.length === 0 ? (
              <View className="py-20 items-center justify-center">
                <Ionicons name="folder-open-outline" size={48} color="#D1D5DB" className="mb-4" />
                <Text className="text-gray-400 text-lg font-medium">No assigned projects found.</Text>
              </View>
            ) : isMobile ? (
              projects.map(p => (
                <View key={p.id} className="bg-white rounded-xl border border-gray-200 p-4 mb-4 shadow-sm">
                  <View className="flex-row items-center mb-3">
                    <View className="w-10 h-10 rounded-full bg-orange-50 items-center justify-center mr-3">
                      <Text className="text-brand-orange font-bold text-lg">{p.name.charAt(0).toUpperCase()}</Text>
                    </View>
                    <View className="flex-1">
                      <Text className="text-brand-text font-bold text-base" numberOfLines={1}>{p.name}</Text>
                      <Text className="text-gray-500 text-xs font-medium">{formatMoney(p.total_budget)}</Text>
                    </View>
                  </View>
                  <View className="flex-row items-center mb-4 pl-[52px]">
                    <View className="flex-row items-center flex-1">
                      <Ionicons name="location-outline" size={14} color="#6B7280" />
                      <Text className="text-gray-500 text-xs ml-1" numberOfLines={1}>{p.location || 'N/A'}</Text>
                    </View>
                    <View className={`px-2 py-1 rounded-full ${p.status === 'active' ? 'bg-[#DCFCE7]' : p.status === 'completed' ? 'bg-blue-100' : 'bg-gray-100'}`}>
                      <Text className={`text-[10px] font-bold uppercase ${p.status === 'active' ? 'text-brand-success' : p.status === 'completed' ? 'text-blue-600' : 'text-gray-500'}`}>
                        {p.status}
                      </Text>
                    </View>
                  </View>
                  <Link href={`/pm/projects/${p.id}` as any} asChild>
                    <Pressable className="bg-brand-orange py-3 rounded-lg items-center">
                      <Text className="text-white text-sm font-bold">View Details</Text>
                    </Pressable>
                  </Link>
                </View>
              ))
            ) : (
              projects.map(p => (
                <View key={p.id} className="flex-row items-center py-4 border-b border-gray-100">
                  <View className="w-[30%] flex-row items-center pr-4">
                    <View className="w-8 h-8 bg-orange-100 rounded items-center justify-center mr-3">
                      <Text className="text-brand-orange font-bold text-xs">{p.name.charAt(0)}</Text>
                    </View>
                    <View>
                      <Text className="text-brand-text font-semibold text-sm truncate">{p.name}</Text>
                      <Text className="text-gray-400 text-[10px]">ID: {p.id.slice(0, 8)}...</Text>
                    </View>
                  </View>

                  <View className="w-[20%] pr-2">
                    <Text className="text-gray-600 text-sm truncate">{p.location || 'N/A'}</Text>
                  </View>

                  <View className="w-[15%]">
                    <Text className="text-brand-text text-sm font-medium">
                      {p.total_budget ? `Rs. ${p.total_budget.toLocaleString()}` : 'TBD'}
                    </Text>
                  </View>

                  <View className="w-[15%]">
                    <View className={`px-2 py-1 rounded self-start ${p.status === 'active' ? 'bg-[#DCFCE7]' : p.status === 'completed' ? 'bg-blue-100' : 'bg-gray-100'}`}>
                      <Text className={`text-[10px] font-bold uppercase ${p.status === 'active' ? 'text-brand-success' : p.status === 'completed' ? 'text-blue-600' : 'text-gray-500'}`}>
                        {p.status}
                      </Text>
                    </View>
                  </View>

                  <View className="flex-1 flex-row justify-end space-x-2 pl-1">
                    <Link href={`/pm/projects/${p.id}` as any} asChild>
                      <Pressable className="bg-brand-orange px-3 py-1.5 rounded-md shadow-sm">
                        <Text className="text-white text-xs font-bold">View Details</Text>
                      </Pressable>
                    </Link>
                  </View>
                </View>
              ))
            )}
          </View>
        </ScrollView>
      </View>
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Alert } from 'react-native';
import { supabase } from '../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';
import { QRScanner } from '../../../components/worker/QRScanner';

export default function SMAttendancePage() {
  const [loading, setLoading] = useState(true);
  const [projects, setProjects] = useState<any[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  
  const [projectWorkers, setProjectWorkers] = useState<any[]>([]);
  const [todayAttendance, setTodayAttendance] = useState<any[]>([]);

  // Scanner State
  const [isScanning, setIsScanning] = useState(false);
  
  const getTodayDateString = () => {
    return new Date().toISOString().split('T')[0];
  };

  const fetchAttendanceData = async () => {
    try {
      setLoading(true);
      const { data: sessionData } = await supabase.auth.getSession();
      if (!sessionData?.session) return;
      const userId = sessionData.session.user.id;

      // 1. Fetch projects through the site-manager assignment relation
      const { data: assignments } = await supabase
        .from('site_manager_sites')
        .select('project_id')
        .eq('site_manager_id', userId);
      const projectIds = assignments?.map((assignment) => assignment.project_id) || [];
      const { data: projectsData } = projectIds.length
        ? await supabase.from('projects').select('id, name, location').in('id', projectIds).eq('status', 'active')
        : { data: [] };
        
      const parsedProjects = projectsData || [];
      setProjects(parsedProjects);

      if (parsedProjects.length > 0) {
        const currentProject = activeProjectId || parsedProjects[0].id;
        if (!activeProjectId) setActiveProjectId(currentProject);

        // 2. Fetch today's labour records for the active project
        const todayStr = getTodayDateString();
        const { data: labourData } = await supabase
          .from('labour')
          .select('*')
          .eq('assigned_project_id', currentProject)
          .eq('date', todayStr);

        setTodayAttendance(labourData || []);
        
        // 3. Fetch workers from profiles
        const { data: workerProfiles } = await supabase
          .from('profiles')
          .select('id, full_name, qr_code')
          .eq('role', 'worker');
          
        setProjectWorkers(workerProfiles || []);
      }
    } catch (error: any) {
      console.error('Error fetching attendance data', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAttendanceData();
  }, [activeProjectId]);

  const markAttendance = async (qrCode: string) => {
    if (!activeProjectId) return;
    try {
      const session = await supabase.auth.getSession();
      const token = session.data.session?.access_token;
      
      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/labour/scan`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          qr_code: qrCode,
          project_id: activeProjectId
        })
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.detail || 'Scan failed');
      }

      fetchAttendanceData();
      Alert.alert('Success', `${result.worker_name} ${result.action === 'check_in' ? 'Clocked In' : 'Clocked Out'}!`);
      if (isScanning) setIsScanning(false);
      
    } catch (error: any) {
      Alert.alert('Error', error.message);
    }
  };

  const getAttendanceStatus = (workerName: string) => {
    const record = todayAttendance.find(a => a.worker_name === workerName);
    return record ? record.status : 'Pending';
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Daily Attendance" />
      
      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : (
        <View className="flex-1">
          {projects.length === 0 ? (
            <View className="flex-1 items-center justify-center p-8">
              <Ionicons name="alert-circle-outline" size={48} color="#D1D5DB" />
              <Text className="text-gray-400 text-lg font-medium text-center mt-4">You have no assigned projects.</Text>
            </View>
          ) : (
            <>
              {/* Project Selector Tabs */}
              <View className="bg-white px-6 pt-4 border-b border-gray-200">
                <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row">
                  {projects.map(project => (
                    <Pressable 
                      key={project.id}
                      onPress={() => setActiveProjectId(project.id)}
                      className={`mr-6 pb-3 border-b-2 ${activeProjectId === project.id ? 'border-brand-orange' : 'border-transparent'}`}
                    >
                      <Text className={`font-bold text-base ${activeProjectId === project.id ? 'text-brand-orange' : 'text-gray-500'}`}>
                        {project.name}
                      </Text>
                    </Pressable>
                  ))}
                </ScrollView>
              </View>

              <ScrollView className="flex-1 p-8" showsVerticalScrollIndicator={false}>
                
                <View className="flex-row justify-between items-center mb-6">
                  <View>
                    <Text className="text-2xl font-bold text-gray-800">Today&apos;s Attendance</Text>
                    <Text className="text-gray-500">{new Date().toDateString()}</Text>
                  </View>
                  
                  <Pressable 
                    onPress={() => setIsScanning(true)}
                    className="bg-brand-orange px-5 py-3 rounded-xl flex-row items-center shadow-sm"
                  >
                    <Ionicons name="qr-code-outline" size={20} color="white" style={{ marginRight: 8 }} />
                    <Text className="text-white font-bold text-base">Scan to Clock-In</Text>
                  </Pressable>
                </View>

                <View className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                  <View className="flex-row py-4 px-6 border-b border-gray-100 bg-gray-50">
                    <Text className="flex-1 text-xs font-bold text-gray-500 uppercase">Worker Name</Text>
                    <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase">Status</Text>
                    <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase text-right">Action</Text>
                  </View>

                  {projectWorkers.length === 0 ? (
                    <View className="p-10 items-center justify-center">
                      <Ionicons name="people-outline" size={48} color="#E5E7EB" />
                      <Text className="text-gray-400 mt-4 font-medium">No workers found.</Text>
                    </View>
                  ) : (
                    projectWorkers.map((worker) => {
                      const status = getAttendanceStatus(worker.full_name);
                      
                      return (
                        <View key={worker.id} className="flex-row items-center py-4 px-6 border-b border-gray-50">
                          <View className="flex-1 flex-row items-center">
                            <View className="w-8 h-8 bg-blue-100 rounded-full items-center justify-center mr-3">
                              <Ionicons name="person" size={14} color="#3B82F6" />
                            </View>
                            <Text className="font-bold text-gray-800">{worker.full_name || 'Unknown Worker'}</Text>
                          </View>

                          <View className="w-1/4">
                            {status === 'Pending' ? (
                              <Text className="text-gray-400 font-semibold italic">Pending</Text>
                            ) : status === 'Present' ? (
                              <Text className="text-green-600 font-bold bg-green-100 px-2 py-1 rounded self-start">Present</Text>
                            ) : (
                              <Text className="text-red-600 font-bold bg-red-100 px-2 py-1 rounded self-start">Absent</Text>
                            )}
                          </View>

                          <View className="w-1/4 flex-row justify-end">
                            {status === 'Pending' && worker.qr_code && (
                              <Text className="text-gray-400 text-xs">Scan QR to clock in</Text>
                            )}
                          </View>
                        </View>
                      );
                    })
                  )}
                </View>
              </ScrollView>
            </>
          )}
        </View>
      )}

      {isScanning && <QRScanner onScan={markAttendance} onClose={() => setIsScanning(false)} />}

    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator, Pressable, Alert, TextInput } from 'react-native';
import { supabase } from '../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';

export default function SMMaterialsPage() {
  const [loading, setLoading] = useState(true);
  const [projects, setProjects] = useState<any[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<'stock' | 'request'>('stock');
  const [projectStock, setProjectStock] = useState<any[]>([]);
  const [myRequests, setMyRequests] = useState<any[]>([]);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);

  // Form State
  const [itemName, setItemName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState('units');

  const fetchMaterialsData = async () => {
    try {
      setLoading(true);
      const { data: sessionData } = await supabase.auth.getSession();
      if (!sessionData?.session) return;
      const userId = sessionData.session.user.id;
      setCurrentUserId(userId);

      // 1. Fetch projects through the site-manager assignment relation
      const { data: assignments } = await supabase
        .from('site_manager_sites')
        .select('project_id')
        .eq('site_manager_id', userId);
      const projectIds = assignments?.map((assignment) => assignment.project_id) || [];
      const { data: projectsData } = projectIds.length
        ? await supabase.from('projects').select('id, name').in('id', projectIds).eq('status', 'active')
        : { data: [] };

      const parsedProjects = projectsData || [];
      setProjects(parsedProjects);

      if (parsedProjects.length > 0) {
        const currentProject = activeProjectId || parsedProjects[0].id;
        if (!activeProjectId) setActiveProjectId(currentProject);

        // 2. Fetch materials for the active project
        const { data: stockData } = await supabase
          .from('materials')
          .select('*')
          .eq('project_id', currentProject)
          .order('created_at', { ascending: false });

        setProjectStock(stockData || []);

        // 3. Fetch past requests by this user
        const { data: reqData } = await supabase
          .from('material_requests')
          .select('*, projects(name)')
          .eq('requested_by', userId)
          .order('created_at', { ascending: false });

        setMyRequests(reqData || []);
      }
    } catch (error: any) {
      console.error('Error fetching materials data', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMaterialsData();
  }, [activeProjectId, activeTab]);

  const handleSubmitRequest = async () => {
    if (!itemName || !quantity || !activeProjectId || !currentUserId) {
      Alert.alert('Error', 'Please fill in all fields.');
      return;
    }

    try {
      setLoading(true);
      const { error } = await supabase
        .from('material_requests')
        .insert({
          project_id: activeProjectId,
          requested_by: currentUserId,
          item_name: itemName,
          quantity: Number(quantity),
          unit: unit,
          status: 'Pending Approval'
        });

      if (error) throw error;

      Alert.alert('Success', 'Material request submitted to Project Manager!');
      setItemName('');
      setQuantity('');
      setActiveTab('stock');
      fetchMaterialsData();
    } catch (error: any) {
      Alert.alert('Error', error.message);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Pending Approval': return 'bg-yellow-100 text-yellow-800';
      case 'Approved': return 'bg-blue-100 text-blue-800';
      case 'Ordered': return 'bg-purple-100 text-purple-800';
      case 'Delivered': return 'bg-green-100 text-green-800';
      case 'Rejected': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="Site Materials" />

      {projects.length > 0 && (
        <View className="bg-white px-6 pt-4 border-b border-gray-200">
          <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row">
            {projects.map(project => (
              <Pressable 
                key={project.id}
                onPress={() => setActiveProjectId(project.id)}
                className={`mr-6 pb-3 border-b-2 ${activeProjectId === project.id ? 'border-brand-orange' : 'border-transparent'}`}
              >
                <Text className={`font-bold text-base ${activeProjectId === project.id ? 'text-brand-orange' : 'text-gray-500'}`}>
                  {project.name}
                </Text>
              </Pressable>
            ))}
          </ScrollView>
        </View>
      )}

      {/* Tabs */}
      <View className="flex-row px-8 mt-6">
        <Pressable 
          onPress={() => setActiveTab('stock')}
          className={`pb-3 mr-8 border-b-2 ${activeTab === 'stock' ? 'border-brand-text' : 'border-transparent'}`}
        >
          <Text className={`font-bold text-base ${activeTab === 'stock' ? 'text-brand-text' : 'text-gray-500'}`}>Current Stock</Text>
        </Pressable>
        <Pressable 
          onPress={() => setActiveTab('request')}
          className={`pb-3 border-b-2 ${activeTab === 'request' ? 'border-brand-text' : 'border-transparent'}`}
        >
          <Text className={`font-bold text-base ${activeTab === 'request' ? 'text-brand-text' : 'text-gray-500'}`}>Request Materials</Text>
        </Pressable>
      </View>

      <View className="flex-1 p-8">
        {loading ? (
          <ActivityIndicator size="large" color="#F97316" style={{ marginTop: 40 }} />
        ) : projects.length === 0 ? (
          <View className="flex-1 items-center justify-center">
            <Ionicons name="alert-circle-outline" size={48} color="#D1D5DB" />
            <Text className="text-gray-400 text-lg font-medium text-center mt-4">You have no assigned projects.</Text>
          </View>
        ) : activeTab === 'stock' ? (
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 flex-1 overflow-hidden">
            <View className="flex-row py-4 px-6 border-b border-gray-100 bg-gray-50">
              <Text className="flex-[2] text-xs font-bold text-gray-500 uppercase">Item Name</Text>
              <Text className="flex-1 text-xs font-bold text-gray-500 uppercase">Stock</Text>
              <Text className="flex-1 text-xs font-bold text-gray-500 uppercase">Status</Text>
            </View>

            <ScrollView showsVerticalScrollIndicator={false}>
              {projectStock.length === 0 ? (
                <View className="p-10 items-center justify-center">
                  <Ionicons name="cube-outline" size={48} color="#D1D5DB" />
                  <Text className="text-gray-400 mt-4">No materials recorded for this project yet.</Text>
                </View>
              ) : (
                projectStock.map(item => {
                  const isLow = (item.global_stock_quantity || 0) < (item.low_stock_threshold || 0);
                  return (
                    <View key={item.id} className="flex-row items-center py-4 px-6 border-b border-gray-50">
                      <View className="flex-[2]">
                        <Text className="font-bold text-brand-text">{item.item_name}</Text>
                        <Text className="text-gray-400 text-xs">{item.unit}</Text>
                      </View>
                      <View className="flex-1">
                        <Text className={`font-bold ${isLow ? 'text-red-500' : 'text-brand-text'}`}>
                          {item.global_stock_quantity ?? 0}
                        </Text>
                      </View>
                      <View className="flex-1">
                        <View className={`self-start px-2 py-1 rounded ${isLow ? 'bg-red-100' : 'bg-green-100'}`}>
                          <Text className={`text-xs font-bold ${isLow ? 'text-red-700' : 'text-green-700'}`}>
                            {isLow ? 'Low Stock' : 'OK'}
                          </Text>
                        </View>
                      </View>
                    </View>
                  );
                })
              )}
            </ScrollView>
          </View>
        ) : (
          <ScrollView showsVerticalScrollIndicator={false} className="flex-1">
            <View className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 mb-8">
              <Text className="text-xl font-bold text-gray-800 mb-6">New Material Request</Text>

              <View>
                <View className="mb-4">
                  <Text className="text-sm font-bold text-gray-700 mb-2">Item Name</Text>
                  <TextInput
                    value={itemName}
                    onChangeText={setItemName}
                    placeholder="e.g. Portland Cement"
                    className="border border-gray-200 rounded-xl p-4 bg-gray-50"
                  />
                </View>

                <View className="flex-row gap-4 mb-4">
                  <View className="flex-[2]">
                    <Text className="text-sm font-bold text-gray-700 mb-2">Quantity</Text>
                    <TextInput
                      value={quantity}
                      onChangeText={setQuantity}
                      placeholder="e.g. 50"
                      keyboardType="numeric"
                      className="border border-gray-200 rounded-xl p-4 bg-gray-50"
                    />
                  </View>
                  <View className="flex-1">
                    <Text className="text-sm font-bold text-gray-700 mb-2">Unit</Text>
                    <TextInput
                      value={unit}
                      onChangeText={setUnit}
                      placeholder="bags, tons..."
                      className="border border-gray-200 rounded-xl p-4 bg-gray-50"
                    />
                  </View>
                </View>

                <Pressable 
                  onPress={handleSubmitRequest}
                  className="bg-brand-orange py-4 rounded-xl mt-4 items-center"
                >
                  <Text className="text-white font-bold text-base">Submit Request to PM</Text>
                </Pressable>
              </View>
            </View>

            {/* Request History */}
            <Text className="text-lg font-bold text-gray-800 mb-4 px-2">My Recent Requests</Text>
            {myRequests.slice(0, 5).map(req => (
              <View key={req.id} className="bg-white p-4 rounded-xl border border-gray-200 mb-3 flex-row items-center justify-between shadow-sm">
                <View>
                  <Text className="font-bold text-gray-800">{req.item_name}</Text>
                  <Text className="text-gray-500 text-xs mt-1">{req.quantity} {req.unit} • {req.projects?.name}</Text>
                </View>
                <View className={`px-2.5 py-1 rounded-md ${getStatusColor(req.status).split(' ')[0]}`}>
                  <Text className={`text-xs font-bold ${getStatusColor(req.status).split(' ')[1]}`}>{req.status}</Text>
                </View>
              </View>
            ))}
          </ScrollView>
        )}
      </View>
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, Pressable, ActivityIndicator, Alert, Modal, TextInput } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../context/AuthContext';
import { TopNav } from '@/components/common/TopNav';

export default function SiteMaterials() {
  const { user } = useAuth();
  
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  
  // New Request Modal State
  const [showModal, setShowModal] = useState(false);
  const [projects, setProjects] = useState<any[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string>('');
  const [itemName, setItemName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState('pcs');
  const [submitting, setSubmitting] = useState(false);

  const [searchQuery, setSearchQuery] = useState('');

  const loadData = async () => {
    setLoading(true);
    try {
      // Load user's requests
      let query = supabase
        .from('material_requests')
        .select('*, projects(name)')
        .eq('requested_by', user?.id)
        .order('created_at', { ascending: false });
        
      if (searchQuery) {
        query = query.ilike('item_name', `%${searchQuery}%`);
      }

      const { data: reqData } = await query;
      setRequests(reqData || []);

      // Load active projects for dropdown
      const { data: projData } = await supabase.from('projects').select('id, name').eq('status', 'active');
      if (projData) {
        setProjects(projData);
        if (projData.length > 0 && !selectedProjectId) {
          setSelectedProjectId(projData[0].id);
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user) loadData();
  }, [user, searchQuery]);

  const handleSubmitRequest = async () => {
    if (!itemName || !quantity || !selectedProjectId) {
      Alert.alert('Error', 'Please fill all required fields');
      return;
    }

    setSubmitting(true);
    try {
      // 1. Insert request
      const { error } = await supabase.from('material_requests').insert({
        project_id: selectedProjectId,
        requested_by: user?.id,
        item_name: itemName,
        quantity: parseFloat(quantity),
        unit: unit,
        status: 'Pending Approval'
      });

      if (error) throw error;

      // 2. Trigger notification to PM
      await supabase.from('notifications').insert({
        project_id: selectedProjectId,
        target_role: 'Project Manager',
        title: 'New Material Request',
        message: `Site Manager requested ${quantity} ${unit} of ${itemName}. Pending your approval.`,
      });

      Alert.alert('Success', 'Material request submitted to Project Manager.');
      setShowModal(false);
      setItemName('');
      setQuantity('');
      loadData();
    } catch (e: any) {
      Alert.alert('Error', e.message);
    } finally {
      setSubmitting(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Pending Approval': return 'bg-yellow-100 text-yellow-800';
      case 'Approved': return 'bg-blue-100 text-blue-800';
      case 'Ordered': return 'bg-purple-100 text-purple-800';
      case 'Delivered': return 'bg-green-100 text-green-800';
      case 'Rejected': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav 
        title="Material Requests" 
        actionLabel="+ Request Material" 
        onActionPress={() => setShowModal(true)} 
        initialSearchQuery={searchQuery}
        onSearch={setSearchQuery}
      />

      <View className="flex-1 p-8">
        {loading ? (
          <ActivityIndicator size="large" color="#F97316" className="mt-10" />
        ) : (
          <View className="bg-white rounded-2xl shadow-sm border border-gray-100 flex-1 overflow-hidden">
            <View className="flex-row py-4 px-6 border-b border-gray-100 bg-gray-50">
              <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase">Item</Text>
              <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase">Project</Text>
              <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase">Quantity</Text>
              <Text className="w-1/4 text-xs font-bold text-gray-500 uppercase text-right">Status</Text>
            </View>

            <ScrollView showsVerticalScrollIndicator={false}>
              {requests.length === 0 ? (
                <View className="p-10 items-center justify-center">
                  <Ionicons name="cart-outline" size={48} color="#D1D5DB" />
                  <Text className="text-gray-400 mt-4">No material requests found.</Text>
                </View>
              ) : (
                requests.map(req => (
                  <View key={req.id} className="flex-row items-center py-4 px-6 border-b border-gray-50 hover:bg-gray-50 transition-colors">
                    <View className="w-1/4">
                      <Text className="font-bold text-brand-text">{req.item_name}</Text>
                      <Text className="text-xs text-gray-400 mt-1">{new Date(req.created_at).toLocaleDateString()}</Text>
                    </View>
                    <View className="w-1/4">
                      <Text className="text-gray-500 text-sm">{req.projects?.name || 'Unknown'}</Text>
                    </View>
                    <View className="w-1/4">
                      <Text className="text-brand-text font-semibold">{req.quantity} {req.unit}</Text>
                    </View>
                    <View className="w-1/4 flex-row justify-end">
                      <View className={`px-3 py-1 rounded-full ${getStatusColor(req.status).split(' ')[0]}`}>
                        <Text className={`text-xs font-bold ${getStatusColor(req.status).split(' ')[1]}`}>{req.status}</Text>
                      </View>
                    </View>
                  </View>
                ))
              )}
            </ScrollView>
          </View>
        )}
      </View>

      {/* New Request Modal */}
      <Modal visible={showModal} transparent animationType="slide">
        <View className="flex-1 bg-black/50 justify-center items-center p-4">
          <View className="bg-white w-full max-w-md rounded-2xl overflow-hidden shadow-2xl">
            <View className="p-6 border-b border-gray-100 flex-row justify-between items-center bg-brand-light">
              <Text className="text-xl font-bold text-brand-text">Request Material</Text>
              <Pressable onPress={() => !submitting && setShowModal(false)}>
                <Ionicons name="close" size={24} color="#6B7280" />
              </Pressable>
            </View>
            
            <View className="p-6">
              <Text className="text-sm font-semibold text-gray-700 mb-2">Target Project</Text>
              <View className="border border-gray-200 rounded-xl mb-4 overflow-hidden max-h-32">
                <ScrollView nestedScrollEnabled>
                  {projects.map(p => (
                    <Pressable 
                      key={p.id}
                      onPress={() => setSelectedProjectId(p.id)}
                      className={`p-3 border-b border-gray-100 ${selectedProjectId === p.id ? 'bg-orange-50' : 'bg-white'}`}
                    >
                      <Text className={selectedProjectId === p.id ? 'text-brand-orange font-bold' : 'text-gray-600'}>
                        {p.name}
                      </Text>
                    </Pressable>
                  ))}
                </ScrollView>
              </View>

              <Text className="text-sm font-semibold text-gray-700 mb-2">Item Name</Text>
              <TextInput
                className="border border-gray-200 rounded-xl p-3 text-brand-text bg-gray-50 mb-4"
                placeholder="e.g. Steel Rebar 12mm"
                value={itemName}
                onChangeText={setItemName}
              />

              <View className="flex-row gap-4 mb-6">
                <View className="flex-1">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Quantity</Text>
                  <TextInput
                    className="border border-gray-200 rounded-xl p-3 text-brand-text bg-gray-50"
                    placeholder="0"
                    keyboardType="numeric"
                    value={quantity}
                    onChangeText={setQuantity}
                  />
                </View>
                <View className="flex-1">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Unit</Text>
                  <TextInput
                    className="border border-gray-200 rounded-xl p-3 text-brand-text bg-gray-50"
                    placeholder="Bags, Tons, Liters..."
                    value={unit}
                    onChangeText={setUnit}
                  />
                </View>
              </View>

              <Pressable 
                onPress={handleSubmitRequest}
                disabled={submitting}
                className={`py-3 rounded-xl flex-row items-center justify-center ${submitting ? 'bg-orange-300' : 'bg-brand-orange hover:bg-orange-600'}`}
              >
                {submitting ? (
                  <ActivityIndicator size="small" color="white" />
                ) : (
                  <Text className="text-white font-bold text-lg">Submit Request</Text>
                )}
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>

    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, Pressable, ActivityIndicator, Image, Alert, TextInput, Modal, Platform } from 'react-native';
import { supabase } from '../../lib/supabase';
import { Ionicons } from '@expo/vector-icons';
import { useAuth } from '../../context/AuthContext';
import * as ImagePicker from 'expo-image-picker';
import { decode } from 'base64-arraybuffer';
import { useResponsive } from '../../hooks/useResponsive';

export default function SitePhotos() {
  const { user } = useAuth();
  const { isMobile } = useResponsive();
  const [loading, setLoading] = useState(true);
  const [photos, setPhotos] = useState<any[]>([]);

  // Upload Modal State
  const [uploading, setUploading] = useState(false);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [selectedImage, setSelectedImage] = useState<ImagePicker.ImagePickerAsset | null>(null);
  const [description, setDescription] = useState('');

  // Projects State for Dropdown
  const [projects, setProjects] = useState<any[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);

  const loadPhotos = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('site_photos')
        .select('*, projects(name)')
        .order('created_at', { ascending: false });

      if (error) throw error;
      setPhotos(data || []);
    } catch (error: any) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const loadProjects = async () => {
    try {
      const { data, error } = await supabase.from('projects').select('id, name').eq('status', 'active');
      if (!error && data) setProjects(data);
    } catch (e) {}
  };

  useEffect(() => {
    loadPhotos();
    loadProjects();
  }, []);

  const handlePickPhoto = async () => {
    const permissionResult = await ImagePicker.requestMediaLibraryPermissionsAsync();

    if (permissionResult.granted === false) {
      Alert.alert('Permission to access camera roll is required!');
      return;
    }

    const pickerResult = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ['images'],
      allowsEditing: true,
      quality: 0.5,
      base64: true, // Request base64 for easy upload on React Native
    });

    if (!pickerResult.canceled && pickerResult.assets.length > 0) {
      setSelectedImage(pickerResult.assets[0]);
      setDescription('');
      setSelectedProjectId(projects.length > 0 ? projects[0].id : null);
      setShowUploadModal(true);
    }
  };

  const executeUpload = async () => {
    if (!selectedImage || !selectedProjectId) {
      Alert.alert('Error', 'Please select a project first.');
      return;
    }

    setUploading(true);
    try {
      // 1. Upload to Supabase Storage
      const fileExt = selectedImage.uri.split('.').pop() || 'jpeg';
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.${fileExt}`;
      const filePath = `site_uploads/${fileName}`;

      let uploadError;

      if (Platform.OS === 'web') {
        // Web: Fetch Blob and upload
        const response = await fetch(selectedImage.uri);
        const blob = await response.blob();
        const { error } = await supabase.storage.from('project-images').upload(filePath, blob, {
          contentType: `image/${fileExt === 'png' ? 'png' : 'jpeg'}`
        });
        uploadError = error;
      } else {
        // React Native (iOS/Android): Use base64
        if (!selectedImage.base64) throw new Error("Could not read image data.");
        const { error } = await supabase.storage.from('project-images').upload(filePath, decode(selectedImage.base64), {
          contentType: `image/${fileExt === 'png' ? 'png' : 'jpeg'}`
        });
        uploadError = error;
      }

      if (uploadError) throw uploadError;

      // 2. Get Public URL
      const { data: publicUrlData } = supabase.storage.from('project-images').getPublicUrl(filePath);
      const publicUrl = publicUrlData.publicUrl;

      // 3. Save to Database
      const { error: dbError } = await supabase.from('site_photos').insert({
        project_id: selectedProjectId,
        uploader_name: user?.user_metadata?.full_name || 'Site Manager',
        photo_url: publicUrl,
        description: description || 'Progress Photo'
      });

      if (dbError) throw dbError;

      Alert.alert('Success', 'Photo uploaded and saved to cloud successfully!');
      setShowUploadModal(false);
      setSelectedImage(null);
      loadPhotos();
    } catch (error: any) {
      Alert.alert('Upload Error', error.message || 'Ensure the project-images bucket exists and RLS allows inserts.');
    } finally {
      setUploading(false);
    }
  };

  return (
    <View className="flex-1 bg-brand-light p-8">
      <View className="flex-row justify-between items-center mb-8">
        <View>
          <Text className="text-3xl font-bold text-brand-text mb-2">Site Photos</Text>
          <Text className="text-gray-500">Visual progress tracking across all active sites.</Text>
        </View>
        <Pressable 
          onPress={handlePickPhoto}
          className="flex-row items-center bg-brand-orange hover:bg-orange-600 transition-colors px-4 py-3 rounded-xl shadow-sm"
        >
          <Ionicons name="cloud-upload-outline" size={20} color="white" className="mr-2" />
          <Text className="text-white font-bold ml-2">Upload Photo</Text>
        </Pressable>
      </View>

      {/* Upload Modal */}
      <Modal visible={showUploadModal} transparent animationType="slide">
        <View className="flex-1 bg-black/50 justify-center items-center p-4">
          <View className="bg-white w-full max-w-md rounded-3xl overflow-hidden shadow-2xl">
            <View className="p-4 border-b border-gray-100 flex-row justify-between items-center bg-gray-50">
              <Text className="text-lg font-bold text-brand-text">Photo Details</Text>
              <Pressable onPress={() => !uploading && setShowUploadModal(false)}>
                <Ionicons name="close" size={24} color="#6B7280" />
              </Pressable>
            </View>

            <View className="p-6">
              {selectedImage && (
                <Image 
                  source={{ uri: selectedImage.uri }} 
                  className="w-full h-48 rounded-xl bg-gray-100 mb-6" 
                  resizeMode="cover"
                />
              )}

              <Text className="text-sm font-semibold text-gray-700 mb-2">Select Project</Text>
              <View className="border border-gray-200 rounded-xl mb-6 overflow-hidden max-h-32">
                <ScrollView nestedScrollEnabled>
                  {projects.map(p => (
                    <Pressable 
                      key={p.id}
                      onPress={() => setSelectedProjectId(p.id)}
                      className={`p-3 border-b border-gray-100 ${selectedProjectId === p.id ? 'bg-orange-50' : 'bg-white'}`}
                    >
                      <Text className={selectedProjectId === p.id ? 'text-brand-orange font-bold' : 'text-gray-600'}>
                        {p.name}
                      </Text>
                    </Pressable>
                  ))}
                  {projects.length === 0 && <Text className="p-4 text-gray-400">No active projects found.</Text>}
                </ScrollView>
              </View>

              <Text className="text-sm font-semibold text-gray-700 mb-2">Description</Text>
              <TextInput
                className="border border-gray-200 rounded-xl p-3 text-brand-text bg-gray-50 mb-6"
                placeholder="E.g. Foundation poured for Tower A"
                value={description}
                onChangeText={setDescription}
                multiline
                numberOfLines={2}
              />

              <Pressable 
                onPress={executeUpload}
                disabled={uploading || !selectedProjectId}
                className={`py-4 rounded-xl flex-row items-center justify-center ${uploading || !selectedProjectId ? 'bg-orange-300' : 'bg-brand-orange hover:bg-orange-600'}`}
              >
                {uploading ? (
                  <ActivityIndicator size="small" color="white" />
                ) : (
                  <Text className="text-white font-bold text-lg">Confirm Upload</Text>
                )}
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>

      {/* Grid */}
      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : (
        <ScrollView showsVerticalScrollIndicator={false}>
          {photos.length === 0 ? (
            <View className="bg-white p-10 rounded-2xl items-center justify-center border border-gray-100">
              <Ionicons name="images-outline" size={48} color="#9CA3AF" />
              <Text className="text-gray-500 mt-4 text-center">No photos have been uploaded yet.</Text>
            </View>
          ) : (
            <View className="flex-row flex-wrap justify-between">
              {photos.map(photo => (
                <View key={photo.id} style={{ width: isMobile ? '100%' : '48%', backgroundColor: '#fff', borderRadius: 16, overflow: 'hidden', marginBottom: 24, borderWidth: 1, borderColor: '#F3F4F6' }}>
                  <Image 
                    source={{ uri: photo.photo_url }} 
                    style={{ width: '100%', height: 200 }} 
                    resizeMode="cover" 
                  />
                  <View className="p-4">
                    <Text className="font-bold text-brand-text mb-1 truncate">{photo.projects?.name || 'Unknown Site'}</Text>
                    <Text className="text-gray-500 text-xs mb-3">{photo.description}</Text>
                    <View className="flex-row items-center justify-between">
                      <Text className="text-xs text-brand-orange font-semibold">{photo.uploader_name}</Text>
                      <Text className="text-xs text-gray-400">{new Date(photo.created_at).toLocaleDateString()}</Text>
                    </View>
                  </View>
                </View>
              ))}
            </View>
          )}
        </ScrollView>
      )}
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator } from 'react-native';
import { supabase } from '../../../lib/supabase';
import { TopNav } from '@/components/common/TopNav';
import { Ionicons } from '@expo/vector-icons';

export default function WorkerPayrollPage() {
  const [loading, setLoading] = useState(true);
  const [payrollRecords, setPayrollRecords] = useState<any[]>([]);
  const [profile, setProfile] = useState<any>(null);
  const [attendanceSummary, setAttendanceSummary] = useState({ present: 0 });

  useEffect(() => {
    let isMounted = true;

    const fetchPayrollData = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) return;
        const userId = sessionData.session.user.id;

        const profileReq = await supabase.from('profiles').select('*').eq('id', userId).single();
        const workerName = profileReq.data?.full_name;

        let presentCount = 0;
        let salarySlips: any[] = [];

        if (workerName) {
          const [attendanceReq, payrollReq] = await Promise.all([
            supabase.from('labour').select('id', { count: 'exact', head: true }).eq('worker_name', workerName).eq('status', 'Present'),
            supabase.from('salary_slips').select('*').eq('worker_id', userId).order('created_at', { ascending: false }),
          ]);
          presentCount = attendanceReq.count || 0;
          salarySlips = payrollReq.data || [];
        }

        if (isMounted) {
          setProfile(profileReq.data);
          setPayrollRecords(salarySlips);
          setAttendanceSummary({ present: presentCount });
        }
      } catch (error) {
        console.error('Worker payroll error:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    fetchPayrollData();
    return () => { isMounted = false; };
  }, []);

  const dailyWage = 3500; // Base daily rate (Rs. 3,500 as per payroll system)
  const estimatedEarnings = dailyWage * attendanceSummary.present;

  const formatCurrency = (amount: number) => `LKR ${amount.toLocaleString('en-LK')}`;

  return (
    <View className="flex-1 bg-brand-light">
      <TopNav title="My Payroll" showAction={false} />

      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#F97316" />
        </View>
      ) : (
        <ScrollView className="flex-1 p-4 md:p-6 lg:p-8" showsVerticalScrollIndicator={false}>

          {/* Earnings Summary Banner */}
          <View className="bg-gradient-to-r from-brand-orange to-orange-400 rounded-2xl p-8 mb-6 shadow-md bg-brand-orange">
            <Text className="text-white text-sm font-semibold mb-1 opacity-80">Estimated Total Earnings</Text>
            <Text className="text-white text-4xl font-bold">{formatCurrency(estimatedEarnings)}</Text>
            <View className="flex-row mt-4 gap-6">
              <View>
                <Text className="text-white opacity-70 text-xs">Daily Rate</Text>
                <Text className="text-white font-bold mt-1">{formatCurrency(dailyWage)}</Text>
              </View>
              <View>
                <Text className="text-white opacity-70 text-xs">Days Worked</Text>
                <Text className="text-white font-bold mt-1">{attendanceSummary.present}</Text>
              </View>
            </View>
          </View>

          {/* Payroll History */}
          <Text className="text-lg font-bold text-gray-800 mb-4">Salary Slips</Text>
          
          {payrollRecords.length === 0 ? (
            <View className="bg-white rounded-2xl p-12 shadow-sm border border-gray-100 items-center justify-center">
              <Ionicons name="document-text-outline" size={48} color="#E5E7EB" />
              <Text className="text-gray-400 mt-4 font-medium">No salary slips generated yet.</Text>
              <Text className="text-gray-400 text-sm mt-2 text-center">Salary slips are generated by your Project Manager at the end of each pay period.</Text>
            </View>
          ) : (
            <View className="space-y-4">
              {payrollRecords.map(record => (
                <View key={record.id} className="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm">
                  <View className="flex-row items-center justify-between p-5 border-b border-gray-100 bg-gray-50">
                    <View>
                      <Text className="font-bold text-gray-800">
                        Pay Period: {new Date(record.period_start).toLocaleDateString('en-GB', { month: 'short', year: 'numeric' })}
                      </Text>
                      <Text className="text-gray-500 text-xs mt-0.5">
                        {new Date(record.period_start).toLocaleDateString()} – {new Date(record.period_end).toLocaleDateString()}
                      </Text>
                    </View>
                    <View className={`px-3 py-1.5 rounded-full ${record.status === 'Paid' ? 'bg-green-100' : 'bg-yellow-100'}`}>
                      <Text className={`text-xs font-bold ${record.status === 'Paid' ? 'text-green-700' : 'text-yellow-700'}`}>
                        {record.status}
                      </Text>
                    </View>
                  </View>
                  <View className="p-5 flex-row justify-between">
                    <View>
                      <Text className="text-gray-500 text-xs">Days Worked</Text>
                      <Text className="font-bold text-gray-800 mt-1">{record.total_days || 0}</Text>
                    </View>
                    <View>
                      <Text className="text-gray-500 text-xs">Overtime Hrs</Text>
                      <Text className="font-bold text-gray-800 mt-1">{record.overtime_hours || 0} hrs</Text>
                    </View>
                    <View>
                      <Text className="text-gray-500 text-xs">Total Payout</Text>
                      <Text className="font-bold text-brand-orange mt-1 text-lg">{formatCurrency(record.total_payout || 0)}</Text>
                    </View>
                  </View>
                </View>
              ))}
            </View>
          )}
        </ScrollView>
      )}
    </View>
  );
}

import React, { useEffect, useState } from 'react';
import { View, Text, Pressable, ScrollView, ActivityIndicator, Modal, TextInput, Alert } from 'react-native';
