const ClientDetailsModal = ({ client, visible, onClose, onUpdate }: { client: any, visible: boolean, onClose: () => void, onUpdate: () => void }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editName, setEditName] = useState('');
  const [editCompany, setEditCompany] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (client) {
      setEditName(client.full_name || '');
      setEditCompany(client.company_name || '');
      setIsEditing(false);
    }
  }, [client, visible]);

  if (!client) return null;

  const handleSave = async () => {
    setLoading(true);
    try {
      await api.put(`/clients/${client.id}`, { name: editName, company: editCompany });
      onUpdate();
      onClose();
    } catch (e: any) {
      if (typeof window !== 'undefined') {
        window.alert(e.message || 'Failed to update client');
      } else {
        Alert.alert('Error', e.message || 'Failed to update client');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    Alert.alert('Delete Client', 'Are you sure you want to delete this client profile? This action cannot be undone.', [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Delete', style: 'destructive', onPress: async () => {
        setLoading(true);
        try {
          await api.delete(`/clients/${client.id}`);
          onUpdate();
          onClose();
        } catch (e: any) {
          Alert.alert('Error', e.message || 'Failed to delete client');
        } finally {
          setLoading(false);
        }
      } },
    ]);
  };
  
  return (
    <Modal visible={visible} transparent animationType="fade">
      <View className="flex-1 bg-black/50 items-center justify-center p-4">
        <View className="bg-white w-full max-w-lg rounded-2xl shadow-xl overflow-hidden">
          <View className="flex-row justify-between items-center p-6 border-b border-gray-100 bg-brand-light">
            <Text className="text-xl font-bold text-brand-text">Client Details</Text>
            <Pressable onPress={onClose} className="p-2 rounded-full hover:bg-gray-200 transition-colors">
              <Ionicons name="close" size={24} color="#6B7280" />
            </Pressable>
          </View>
          <ScrollView className="p-6 max-h-[70vh]">
            <View className="items-center mb-6">
              <View className="w-20 h-20 rounded-full bg-blue-500 items-center justify-center mb-4">
                <Text className="text-white text-2xl font-bold">{client.full_name?.substring(0, 2).toUpperCase()}</Text>
              </View>
              {isEditing ? (
                <TextInput 
                  value={editName}
                  onChangeText={setEditName}
                  className="border border-gray-300 rounded-lg px-4 py-2 text-base text-brand-text w-full mb-2"
                  placeholder="Full Name"
                />
              ) : (
                <Text className="text-xl font-bold text-brand-text">{client.full_name}</Text>
              )}
              <Text className="text-gray-500">{client.email}</Text>
            </View>
            <View className="mb-4">
              <Text className="text-sm font-bold text-gray-500 mb-1">Company Name</Text>
              {isEditing ? (
                <TextInput 
                  value={editCompany}
                  onChangeText={setEditCompany}
                  className="border border-gray-300 rounded-lg px-4 py-2 text-base text-brand-text w-full"
                  placeholder="Company Name"
                />
              ) : (
                <Text className="text-base text-brand-text">{client.company_name || 'N/A'}</Text>
              )}
            </View>
            <View className="mb-4">
              <Text className="text-sm font-bold text-gray-500 mb-1">Role</Text>
              <Text className="text-base text-brand-text uppercase">{client.role}</Text>
            </View>
            <View className="mb-4">
              <Text className="text-sm font-bold text-gray-500 mb-1">Member Since</Text>
              <Text className="text-base text-brand-text">{new Date(client.created_at).toLocaleDateString()}</Text>
            </View>
          </ScrollView>

          {/* Footer Actions */}
          <View className="p-6 border-t border-gray-100 flex-row justify-end space-x-3 bg-gray-50">
            {isEditing ? (
              <>
                <Pressable onPress={() => setIsEditing(false)} className="px-4 py-2 rounded-lg bg-gray-200">
                  <Text className="text-gray-700 font-semibold">Cancel</Text>
                </Pressable>
                <Pressable onPress={handleSave} disabled={loading} className={`px-4 py-2 rounded-lg ${loading ? 'bg-blue-300' : 'bg-blue-600'}`}>
                  <Text className="text-white font-semibold">{loading ? 'Saving...' : 'Save'}</Text>
                </Pressable>
              </>
            ) : (
              <>
                <Pressable onPress={handleDelete} disabled={loading} className="px-4 py-2 rounded-lg bg-red-100">
                  <Text className="text-red-600 font-semibold">{loading ? '...' : 'Delete'}</Text>
                </Pressable>
                <Pressable onPress={() => setIsEditing(true)} className="px-4 py-2 rounded-lg bg-blue-100">
                  <Text className="text-blue-600 font-semibold">Edit</Text>
                </Pressable>
              </>
            )}
          </View>
        </View>
      </View>
    </Modal>
  );
};

export const ClientAccountsPanel = ({ refreshTrigger = 0, searchQuery = '', pmId }: { refreshTrigger?: number, searchQuery?: string, pmId?: string }) => {
  const [clients, setClients] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedClient, setSelectedClient] = useState<any>(null);
  const [localRefreshTrigger, setLocalRefreshTrigger] = useState(0);

  useEffect(() => {
    let isMounted = true;
    
    const loadClients = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        // Ideally, if pmId is passed, we join on projects where pm_id = pmId and project.client_id = profile.id
        // Since we don't have a direct link in the profiles table, we first find the client IDs.
        let allowedClientIds: string[] = [];
        if (pmId) {
          const { data: projects } = await supabase.from('projects').select('client_id').eq('pm_id', pmId);
          if (projects) {
            allowedClientIds = projects.map(p => p.client_id).filter(Boolean);
          }
        }

        let query = supabase
          .from('profiles')
          .select('*')
          .eq('role', 'client')
          .order('created_at', { ascending: false });

        if (pmId) {
          if (allowedClientIds.length > 0) {
            query = query.in('id', allowedClientIds);
          } else {
            // If the PM has no projects with clients, return empty
            if (isMounted) setClients([]);
            if (isMounted) setLoading(false);
            return;
          }
        }

        if (searchQuery) {
          query = query.ilike('email', `%${searchQuery}%`);
        }

        const { data, error } = await query;

        if (error) throw error;
        
        if (isMounted) setClients(data || []);
      } catch (error) {
        console.warn('Failed to load clients:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadClients();
    
    const channel = supabase
      .channel('client_accounts_channel')
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'profiles',
        filter: 'role=eq.client'
      }, () => {
        if (isMounted) {
          loadClients(); 
        }
      })
      .subscribe();
      
    return () => { 
      isMounted = false; 
      supabase.removeChannel(channel);
    };
  }, [refreshTrigger, localRefreshTrigger, searchQuery]);

  const getInitials = (name: string) => {
    if (!name) return 'C';
    const parts = name.split(' ');
    if (parts.length >= 2) {
      return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
    }
    return name.substring(0, 2).toUpperCase();
  };

  const getAvatarColor = (index: number) => {
    const colors = ['bg-blue-500', 'bg-purple-500', 'bg-teal-500', 'bg-orange-500', 'bg-pink-500'];
    return colors[index % colors.length];
  };

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 min-h-[400px]">
      <View className="flex-row justify-between items-center mb-6">
        <View>
          <Text className="text-lg font-bold text-brand-text mb-1">Client Accounts</Text>
          <Text className="text-brand-text-muted text-xs">Manage access and project sharing</Text>
        </View>
        <Pressable>
          <Text className="text-brand-orange text-sm font-semibold">View all</Text>
        </Pressable>
      </View>

      {loading ? (
        <View className="flex-1 items-center justify-center py-10">
          <ActivityIndicator size="large" color="#3B82F6" />
        </View>
      ) : (
        <ScrollView showsVerticalScrollIndicator={false}>
          {clients.length === 0 ? (
            <View className="py-10 items-center">
              <Text className="text-gray-400">No clients invited yet.</Text>
            </View>
          ) : (
            clients.map((client, i) => {
              const colorClass = getAvatarColor(i);
              
              return (
                <ClientCard 
                  key={client.id}
                  initials={client.full_name?.substring(0, 2).toUpperCase() || 'NA'}
                  colorClass={colorClass}
                  projectName="Multiple Projects"
                  accessLevel="Full Access"
                  companyName={client.company_name || 'N/A'}
                  clientName={client.full_name || 'Unknown'}
                  email={client.email}
                  onViewDetails={() => setSelectedClient(client)}
                />
              );
            })
          )}
        </ScrollView>
      )}
      <ClientDetailsModal 
        client={selectedClient} 
        visible={!!selectedClient} 
        onClose={() => setSelectedClient(null)} 
        onUpdate={() => setLocalRefreshTrigger(prev => prev + 1)} // we also need a local state trigger to re-fetch
      />
    </View>
  );
};

import React, { useEffect } from 'react';
import { ViewStyle, StyleProp } from 'react-native';
import Animated, { 
  useSharedValue, 
  useAnimatedStyle, 
  withTiming, 
  withDelay, 
  withSpring,
  Easing 
} from 'react-native-reanimated';

interface AnimatedCardProps {
  children: React.ReactNode;
  delay?: number;
  style?: StyleProp<ViewStyle>;
  className?: string;
  direction?: 'up' | 'down' | 'left' | 'right';
  duration?: number;
}

export const AnimatedCard: React.FC<AnimatedCardProps> = ({ 
  children, 
  delay = 0, 
  style, 
  className,
  direction = 'up',
  duration = 500
}) => {
  const opacity = useSharedValue(0);
  const translate = useSharedValue(50);

  useEffect(() => {
    // Fade in
    opacity.value = withDelay(
      delay, 
      withTiming(1, { duration, easing: Easing.out(Easing.exp) })
    );

    // Slide in
    translate.value = withDelay(
      delay,
      withSpring(0, {
        damping: 15,
        stiffness: 100,
        mass: 1
      })
    );
  }, []);

  const animatedStyle = useAnimatedStyle(() => {
    let transform = [];
    
    switch (direction) {
      case 'up':
        transform.push({ translateY: translate.value });
        break;
      case 'down':
        transform.push({ translateY: -translate.value });
        break;
      case 'left':
        transform.push({ translateX: translate.value });
        break;
      case 'right':
        transform.push({ translateX: -translate.value });
        break;
    }

    return {
      opacity: opacity.value,
      transform,
    };
  });

  return (
    <Animated.View style={[animatedStyle, style]} className={className}>
      {children}
    </Animated.View>
  );
};

import React, { useEffect, useState, useRef } from 'react';
import { View, Text, Pressable, Platform, Animated, Easing, TouchableOpacity, useWindowDimensions, StyleSheet, ScrollView } from 'react-native';
import { Link, usePathname, useRouter } from 'expo-router';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../lib/supabase';
import { useTheme } from '../../context/ThemeContext';
import { useSidebar } from '../../context/SidebarContext';
import { Ionicons } from '@expo/vector-icons';
import { LogoutConfirmationModal } from './LogoutConfirmationModal';
import { buildNotificationFilter } from '../../utils/notifications';

export type NavItem = {
  label: string;
  href: string;
  IconFamily: any;
  iconName: string;
  badge?: number;
};

// Modified for Expo Go mobile compatibility
export const MobileSidebar = ({ navItems, basePath = '' }: { navItems: NavItem[], basePath?: string }) => {
  const pathname = usePathname();
  const { user, role } = useAuth();
  const router = useRouter();
  const { isDark } = useTheme();
  const { isOpen, setIsOpen } = useSidebar();
  const { width } = useWindowDimensions();
  const isMobile = Platform.OS !== 'web' || width < 1024;

  const slideAnim = useRef(new Animated.Value(-300)).current;
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const [logoutModalVisible, setLogoutModalVisible] = useState(false);

  useEffect(() => {
    if (!isMobile) return;

    if (isOpen) {
      Animated.parallel([
        Animated.timing(slideAnim, {
          toValue: 0,
          duration: 300,
          easing: Easing.out(Easing.cubic),
          useNativeDriver: true,
        }),
        Animated.timing(fadeAnim, {
          toValue: 1,
          duration: 300,
          useNativeDriver: true,
        })
      ]).start();
    } else {
      Animated.parallel([
        Animated.timing(slideAnim, {
          toValue: -300,
          duration: 300,
          easing: Easing.in(Easing.cubic),
          useNativeDriver: true,
        }),
        Animated.timing(fadeAnim, {
          toValue: 0,
          duration: 300,
          useNativeDriver: true,
        })
      ]).start();
    }
  }, [isOpen, isMobile]);

  const completeLogout = async () => {
    await supabase.auth.signOut();
    router.replace('/login');
  };

  const handleLogout = () => {
    setLogoutModalVisible(true);
  };

  const getInitials = (email?: string) => {
    return email ? email.substring(0, 2).toUpperCase() : 'U';
  };

  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    if (!user) return;
    let isMounted = true;
    const fetchUnread = async () => {
      const { count } = await supabase
        .from('notifications')
        .select('*', { count: 'exact', head: true })
        .eq('is_read', false)
        .or(buildNotificationFilter(user.id, role));
      if (count !== null && isMounted) setUnreadCount(count);
    };
    fetchUnread();

    // Quick polling fallback if realtime fails
    const interval = setInterval(fetchUnread, 15000);
    return () => { isMounted = false; clearInterval(interval); };
  }, [user, role]);

  const SidebarContent = () => (
    <View className={`w-full max-w-[260px] h-full py-6 flex-col border-r ${isMobile ? 'bg-slate-900 border-slate-800' : (isDark ? 'bg-[#0B0F19] border-gray-900' : 'bg-white border-gray-100')}`}>
      {/* Logo Area */}
      <View className="px-4 mb-8">
        <Text className={`font-bold text-xl ${isMobile || isDark ? 'text-white' : 'text-brand-text'}`}>Construct<Text style={{ color: '#F97316' }}>Ai</Text></Text>
        <Text className={`text-xs mt-1 ${isMobile || isDark ? 'text-gray-400' : 'text-gray-500'}`}>AI Construction Platform</Text>
      </View>

      {/* Navigation */}
      <ScrollView className="flex-1 min-h-0 px-3" contentContainerStyle={{ paddingBottom: 12 }}>
        {navItems.map((item) => {
          const fullHref = item.href.startsWith(`${basePath}/`)
            ? item.href
            : `${basePath}${item.href}`;
          const isDashboard = item.href === '/dashboard';
          const isActive = isDashboard
            // Dashboard: exact match only — never highlight for sub-routes
            ? pathname === fullHref || pathname === basePath
            // Other items: exact OR any sub-route, but never bleed into dashboard
            : (pathname === fullHref || pathname.startsWith(`${fullHref}/`)) && !isDashboard;
          const IconFamily = item.IconFamily;

          return (
            <Link key={item.label} href={fullHref as any} asChild onPress={() => isMobile && setIsOpen(false)}>
              <TouchableOpacity activeOpacity={0.7} className={`flex-row items-center py-3 px-3 rounded-lg mb-1 ${isActive ? (isMobile || isDark ? 'bg-gray-800' : 'bg-brand-orange bg-opacity-10') : (isMobile || isDark ? 'hover:bg-gray-800/50' : 'hover:bg-gray-50 hover:bg-opacity-10')}`}>
                <IconFamily 
                  name={item.iconName as any} 
                  size={18} 
                  color={isActive ? '#F97316' : (isMobile || isDark ? '#9CA3AF' : '#6B7280')} 
                  style={{ marginRight: 12 }}
                />
                <Text className={`text-sm flex-1 ${isActive ? (isMobile || isDark ? 'text-white font-semibold' : 'text-brand-text font-semibold') : (isMobile || isDark ? 'text-gray-300' : 'text-gray-600')}`}>
                  {item.label}
                </Text>
                {(item.label === 'Notifications' && unreadCount > 0) ? (
                  <View className="bg-brand-orange w-5 h-5 rounded-full items-center justify-center">
                    <Text className="text-white text-[10px] font-bold">{unreadCount}</Text>
                  </View>
                ) : (item.badge && item.label !== 'Notifications') ? (
                  <View className="bg-brand-orange w-5 h-5 rounded-full items-center justify-center">
                    <Text className="text-white text-[10px] font-bold">{item.badge}</Text>
                  </View>
                ) : null}
              </TouchableOpacity>
            </Link>
          );
        })}
      </ScrollView>

      {/* User Profile */}
      <View className="px-4 mt-4 flex-shrink-0">
        <View className={`flex-row items-center justify-between pt-4 border-t ${isMobile || isDark ? 'border-gray-800' : 'border-gray-100'}`}>
          <View className="flex-row items-center flex-1">
            <View className={`w-8 h-8 rounded-full items-center justify-center mr-3 ${isMobile || isDark ? 'bg-gray-800' : 'bg-gray-200'}`}>
              <Text className={`text-xs font-bold ${isMobile || isDark ? 'text-white' : 'text-brand-text'}`}>{getInitials(user?.email)}</Text>
            </View>
            <View className="flex-1 pr-2">
              <Text className={`text-sm font-semibold truncate ${isMobile || isDark ? 'text-white' : 'text-brand-text'}`} numberOfLines={1}>{user?.email || 'User'}</Text>
              <Text className={`text-xs ${isMobile || isDark ? 'text-gray-400' : 'text-gray-500'}`}>{role || 'Loading...'}</Text>
            </View>
          </View>
          <Pressable onPress={handleLogout} className="p-2">
            <Ionicons name="log-out-outline" size={20} color="#9CA3AF" />
          </Pressable>
        </View>
      </View>
    </View>
  );

  if (!isMobile) {
    return (
      <>
        <SidebarContent />
        <LogoutConfirmationModal
          visible={logoutModalVisible}
          isDark={isDark}
          onCancel={() => setLogoutModalVisible(false)}
          onConfirm={() => { setLogoutModalVisible(false); void completeLogout(); }}
        />
      </>
    );
  }

  return (
    <>
      <View style={StyleSheet.absoluteFill} pointerEvents={isOpen ? 'auto' : 'none'} className="z-50">
      <Animated.View style={[StyleSheet.absoluteFill, { opacity: fadeAnim }]}>
        <TouchableOpacity 
          onPress={() => setIsOpen(false)}
          activeOpacity={1}
          style={{ position:'absolute', top:0, left:0, right:0, bottom:0, backgroundColor:'rgba(0,0,0,0.5)' }} 
        />
      </Animated.View>
      <Animated.View style={{ flex: 1, transform: [{ translateX: slideAnim }] }}>
        <SidebarContent />
      </Animated.View>
      </View>
      <LogoutConfirmationModal
        visible={logoutModalVisible}
        isDark={isDark}
        onCancel={() => setLogoutModalVisible(false)}
        onConfirm={() => { setLogoutModalVisible(false); void completeLogout(); }}
      />
    </>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, Modal, Pressable, ScrollView, Switch, ActivityIndicator, Platform } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../context/AuthContext';
import { usePushNotifications } from '../../hooks/usePushNotifications';
import { useRealtimeNotifications } from '../../hooks/useRealtimeNotifications';

export const NotificationPanel = ({ visible, onClose }: { visible: boolean; onClose: () => void }) => {
  const { user, role } = useAuth();
  const [activeTab, setActiveTab] = useState<'inbox' | 'settings'>('inbox');
  const [pushEnabled, setPushEnabled] = useState(false);
  
  const { notifications, loading, markAsRead, markAllAsRead } = useRealtimeNotifications();

  // Initialize Push Token listener (already handled in root layout, but we need it to trigger permission requests)
  const { expoPushToken, requestToken } = usePushNotifications(user?.id || null);

  useEffect(() => {
    if (visible && user) {
      checkPushStatus();
    }
  }, [visible, user]);

  const checkPushStatus = async () => {
    if (!user) return;
    try {
      const { data } = await supabase.from('profiles').select('expo_push_token').eq('id', user.id).single();
      setPushEnabled(!!data?.expo_push_token);
    } catch (e) {}
  };

  const togglePush = async (val: boolean) => {
    setPushEnabled(val);
    if (!user) return;

    if (val) {
      // User turned on push notifications
      if (Platform.OS === 'web') {
        alert('Push notifications require a physical iOS or Android device.');
        setPushEnabled(false);
        return;
      }
      
      const token = await requestToken();
      if (token) {
        await supabase.from('profiles').update({ expo_push_token: token }).eq('id', user.id);
      } else {
        setPushEnabled(false); // Revert if permission denied
      }
    } else {
      // User turned off
      await supabase.from('profiles').update({ expo_push_token: null }).eq('id', user.id);
    }
  };

  return (
    <Modal visible={visible} transparent animationType="fade">
      <View className="flex-1 bg-black/30 items-end justify-start pt-16 pr-4">
        <View className="bg-white w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden mt-2">
          
          <View className="flex-row justify-between items-center p-4 border-b border-gray-100 bg-brand-light">
            <Text className="text-lg font-bold text-brand-text">Notifications</Text>
            <Pressable onPress={onClose} className="p-1 rounded-full hover:bg-gray-200 transition-colors">
              <Ionicons name="close" size={24} color="#6B7280" />
            </Pressable>
          </View>

          <View className="flex-row border-b border-gray-100 px-4">
            <Pressable onPress={() => setActiveTab('inbox')} className={`py-3 mr-6 ${activeTab === 'inbox' ? 'border-b-2 border-brand-orange' : ''}`}>
              <Text className={`font-semibold ${activeTab === 'inbox' ? 'text-brand-orange' : 'text-gray-400'}`}>Inbox</Text>
            </Pressable>
            <Pressable onPress={() => setActiveTab('settings')} className={`py-3 ${activeTab === 'settings' ? 'border-b-2 border-brand-orange' : ''}`}>
              <Text className={`font-semibold ${activeTab === 'settings' ? 'text-brand-orange' : 'text-gray-400'}`}>Settings</Text>
            </Pressable>
          </View>

          <ScrollView className="max-h-96 min-h-[250px] bg-gray-50">
            {activeTab === 'inbox' ? (
              loading ? (
                <ActivityIndicator color="#F97316" className="mt-8" />
              ) : notifications.length === 0 ? (
                <View className="items-center justify-center p-8 mt-4">
                  <Ionicons name="notifications-off-outline" size={48} color="#D1D5DB" />
                  <Text className="text-gray-400 mt-2">No new notifications</Text>
                </View>
              ) : (
                notifications.map(n => (
                  <Pressable 
                    key={n.id} 
                    onPress={() => markAsRead(n.id)}
                    className={`p-4 border-b border-gray-100 flex-row ${n.is_read ? 'bg-white opacity-60' : 'bg-orange-50/50'}`}
                  >
                    <View className="flex-1">
                      <View className="flex-row justify-between items-start mb-1">
                        <Text className={`text-sm ${n.is_read ? 'font-semibold text-gray-700' : 'font-bold text-brand-text'}`}>{n.title}</Text>
                        {!n.is_read && <View className="w-2 h-2 bg-brand-orange rounded-full mt-1.5" />}
                      </View>
                      <Text className="text-sm text-gray-500 leading-relaxed">{n.message}</Text>
                      <Text className="text-xs text-gray-400 mt-2">{new Date(n.created_at).toLocaleString()}</Text>
                    </View>
                  </Pressable>
                ))
              )
            ) : (
              <View className="p-6">
                <Text className="text-sm font-semibold text-gray-700 mb-4">Device Preferences</Text>
                <View className="flex-row items-center justify-between bg-white p-4 rounded-xl border border-gray-100">
                  <View className="flex-1 pr-4">
                    <Text className="font-bold text-brand-text mb-1">Push Notifications</Text>
                    <Text className="text-xs text-gray-500">Receive alerts on your device for critical project updates and activities.</Text>
                  </View>
                  <Switch 
                    value={pushEnabled} 
                    onValueChange={togglePush}
                    trackColor={{ false: '#D1D5DB', true: '#FDBA74' }}
                    thumbColor={pushEnabled ? '#F97316' : '#9CA3AF'}
                  />
                </View>
              </View>
            )}
          </ScrollView>

        </View>
      </View>
    </Modal>
  );
};

