export const ActiveProjectsTable = ({ refreshTrigger = 0, searchQuery = '', pmId }: { refreshTrigger?: number, searchQuery?: string, pmId?: string }) => {
  const [projects, setProjects] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showEditModal, setShowEditModal] = useState(false);
  const [selectedProject, setSelectedProject] = useState<any>(null);
  const [localRefresh, setLocalRefresh] = useState(0);

  useEffect(() => {
    let isMounted = true;
    
    const loadProjects = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        let query = supabase
          .from('projects')
          .select('*')
          .eq('status', 'active')
          .order('created_at', { ascending: false });
          
        if (pmId) {
          // Fetch assignments first
          const { data: assignments } = await supabase
            .from('pm_projects')
            .select('project_id')
            .eq('pm_id', pmId);
            
          const projectIds = assignments?.map(a => a.project_id) || [];
          
          if (projectIds.length === 0) {
            if (isMounted) {
              setProjects([]);
              setLoading(false);
            }
            return;
          }
          query = query.in('id', projectIds);
        }
          
        if (searchQuery) {
          query = query.ilike('name', `%${searchQuery}%`);
        }

        const { data, error } = await query;

        if (error) throw error;
        
        if (isMounted) setProjects(data || []);
      } catch (error) {
        console.warn('Failed to load projects:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadProjects();
    
    return () => { isMounted = false; };
  }, [refreshTrigger, searchQuery, localRefresh]);

  const handleManage = (project: any) => {
    setSelectedProject(project);
    setShowEditModal(true);
  };

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 min-h-[300px]">
      <View className="flex-row justify-between items-center mb-4">
        <Text className="text-lg font-bold text-brand-text">Active Projects</Text>
        <Pressable onPress={() => Alert.alert('Info', 'All active projects are currently displayed.')}>
          <Text className="text-brand-orange text-sm font-semibold">View all →</Text>
        </Pressable>
      </View>

      <View className="flex-1">
        {loading ? (
          <View className="flex-1 justify-center items-center">
            <ActivityIndicator color="#F97316" />
          </View>
        ) : projects.length === 0 ? (
          <View className="flex-1 justify-center items-center">
            <Text className="text-gray-400">No active projects found.</Text>
          </View>
        ) : (
          projects.map(p => (
            <ProjectRow 
              key={p.id}
              project={p}
              onManage={handleManage}
            />
          ))
        )}
      </View>

      <EditProjectModal
        visible={showEditModal}
        onClose={() => setShowEditModal(false)}
        project={selectedProject}
        onProjectUpdated={() => setLocalRefresh(prev => prev + 1)}
      />
    </View>
  );
};

import React, { useEffect, useState, useCallback, useRef } from 'react';
import { View, Text, Pressable, ActivityIndicator } from 'react-native';
import { supabase } from '../../lib/supabase';

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** Returns the last N month labels and their numeric month index (0-based) */
function getLastNMonths(n: number) {
  const now = new Date();
  return Array.from({ length: n }, (_, i) => {
    const d = new Date(now.getFullYear(), now.getMonth() - (n - 1 - i), 1);
    return { label: MONTHS[d.getMonth()], monthIdx: d.getMonth(), year: d.getFullYear() };
  });
}

export const CostTimelineChart = () => {
  const [chartData, setChartData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [maxVal, setMaxVal] = useState(1); // in millions
  const [showForecast, setShowForecast] = useState(true);

  const loadData = useCallback(async () => {
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      if (!sessionData?.session) { setLoading(false); return; }

      const periods = getLastNMonths(7);

      // 1. Fetch all active projects (budget)
      const { data: projects, error: pErr } = await supabase
        .from('projects')
        .select('id, total_budget, created_at')
        .eq('status', 'active');

      if (pErr) throw pErr;

      // 2. Fetch delivered purchase orders (actual spend) for those projects
      const projectIds = (projects || []).map((p: any) => p.id);

      let orders: any[] = [];
      if (projectIds.length > 0) {
        const { data: ord, error: oErr } = await supabase
          .from('purchase_orders')
          .select('project_id, total_amount, created_at')
          .in('project_id', projectIds)
          .eq('status', 'Delivered')
          .order('created_at', { ascending: true });
        if (!oErr && ord) orders = ord;
      }

      // 3. Aggregate into monthly buckets
      const aggregated = periods.map(({ label, monthIdx, year }) => {
        // Actual spend: sum delivered PO amounts in this month/year
        const actualSpend = orders
          .filter((o: any) => {
            const d = new Date(o.created_at);
            return d.getMonth() === monthIdx && d.getFullYear() === year;
          })
          .reduce((sum: number, o: any) => sum + (Number(o.total_amount) || 0), 0) / 1_000_000;

        // Budget: sum project total_budget whose created_at falls in this month/year
        const budgetAlloc = (projects || [])
          .filter((p: any) => {
            const d = new Date(p.created_at);
            return d.getMonth() === monthIdx && d.getFullYear() === year;
          })
          .reduce((sum: number, p: any) => sum + (Number(p.total_budget) || 0), 0) / 1_000_000;

        return { month: label, actual: actualSpend, forecast: budgetAlloc };
      });

      // 4. If no per-month budget data, distribute total budget evenly as forecast
      const totalBudget = (projects || [])
        .reduce((s: number, p: any) => s + (Number(p.total_budget) || 0), 0) / 1_000_000;

      const hasForecast = aggregated.some(a => a.forecast > 0);
      if (!hasForecast && totalBudget > 0) {
        const perMonth = totalBudget / 7;
        aggregated.forEach(a => { a.forecast = perMonth; });
      }

      // 5. Determine chart scale
      const maxFound = Math.max(
        1,
        ...aggregated.map(a => Math.max(a.actual, a.forecast))
      );
      const roundedMax = Math.ceil(maxFound / 10) * 10 || 10;

      setChartData(aggregated);
      setMaxVal(roundedMax);
    } catch (err) {
      console.warn('CostTimelineChart: failed to load data', err);
    } finally {
      setLoading(false);
    }
  }, []);

  // Initial load
  useEffect(() => { loadData(); }, [loadData]);

  // Realtime: re-draw when invoices or projects change
  useEffect(() => {
    const trigger = () => loadData();

    const ordersChannel = supabase
      .channel('chart-purchase-orders')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'purchase_orders' }, trigger)
      .subscribe();

    const projectsChannel = supabase
      .channel('chart-projects')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'projects' }, trigger)
      .subscribe();

    return () => {
      supabase.removeChannel(ordersChannel);
      supabase.removeChannel(projectsChannel);
    };
  }, [loadData]);

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 min-h-[300px]">
      <View className="flex-row justify-between items-start mb-6">
        <View>
          <Text className="text-lg font-bold text-brand-text mb-1">Project Cost vs Timeline (in Millions)</Text>
          <Text className="text-brand-text-muted text-xs">Budget consumption across active projects</Text>
        </View>
        <Pressable 
          className={`flex-row items-center border ${showForecast ? 'border-brand-orange bg-orange-50' : 'border-gray-300 bg-white'} px-3 py-1.5 rounded-full`}
          onPress={() => setShowForecast(!showForecast)}
        >
          <View className={`w-3 h-3 rounded-full mr-1.5 ${showForecast ? 'bg-brand-orange' : 'bg-gray-300'}`} />
          <Text className={`${showForecast ? 'text-brand-orange' : 'text-gray-500'} text-xs font-semibold`}>Budget Plan</Text>
        </Pressable>
      </View>

      {loading ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator color="#F97316" />
        </View>
      ) : (
        <>
          {/* Chart Area */}
          <View className="flex-1 mt-4">
            {/* Y-axis labels */}
            <View className="absolute left-0 top-0 bottom-6 justify-between items-end pr-2 w-10">
              <Text className="text-gray-400 text-[10px]">{maxVal}M</Text>
              <Text className="text-gray-400 text-[10px]">{(maxVal * 0.75).toFixed(0)}M</Text>
              <Text className="text-gray-400 text-[10px]">{(maxVal * 0.5).toFixed(0)}M</Text>
              <Text className="text-gray-400 text-[10px]">{(maxVal * 0.25).toFixed(0)}M</Text>
              <Text className="text-gray-400 text-[10px]">0</Text>
            </View>
            
            {/* Grid lines */}
            <View className="ml-10 flex-1 justify-between pb-6">
              <View className="border-b border-gray-100 w-full" />
              <View className="border-b border-gray-100 w-full" />
              <View className="border-b border-gray-100 w-full" />
              <View className="border-b border-gray-100 w-full" />
              <View className="border-b border-gray-300 w-full" />
            </View>

            {/* Bars Container */}
            <View className="absolute left-10 right-0 top-0 bottom-6 flex-row justify-around items-end pt-2">
              {chartData.map((item, index) => (
                <View key={index} className="flex-row items-end h-full gap-[2px]">
                  {/* Actual spend bar */}
                  {item.actual > 0 ? (
                    <View 
                      className="w-4 bg-brand-dark rounded-t-sm" 
                      style={{ height: `${Math.min(100, (item.actual / maxVal) * 100)}%` }}
                    />
                  ) : (
                    <View className="w-4" />
                  )}
                  {/* Budget / forecast bar */}
                  {showForecast && item.forecast > 0 && (
                    <View 
                      className="w-4 bg-brand-orange rounded-t-sm opacity-70" 
                      style={{ height: `${Math.min(100, (item.forecast / maxVal) * 100)}%` }}
                    />
                  )}
                </View>
              ))}
            </View>

            {/* X-axis labels */}
            <View className="ml-10 flex-row justify-around mt-2">
              {chartData.map((item, index) => (
                <Text key={index} className="text-gray-400 text-[10px] w-8 text-center">
                  {item.month}
                </Text>
              ))}
            </View>
          </View>
          
          {/* Legend */}
          <View className="flex-row justify-center mt-4 gap-6">
            <View className="flex-row items-center">
              <View className="w-3 h-3 bg-brand-dark rounded-sm mr-2" />
              <Text className="text-xs text-gray-500">Actual Spend (Invoices)</Text>
            </View>
            <View className="flex-row items-center">
              <View className="w-3 h-3 bg-brand-orange opacity-70 rounded-sm mr-2" />
              <Text className="text-xs text-gray-500">Planned Budget</Text>
            </View>
          </View>
        </>
      )}
    </View>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { View, Text, TextInput, Pressable, ActivityIndicator, Modal, ScrollView, Platform } from 'react-native';
import { supabase } from '../../lib/supabase';
import { Ionicons } from '@expo/vector-icons';
import { GoogleMap, useLoadScript, Marker } from '@react-google-maps/api';
import { toast } from '../../lib/toast';
import { ProjectAssignmentDropdown } from '../common/ProjectAssignmentDropdown';

type NewProjectModalProps = {
  visible: boolean;
  onClose: () => void;
  onSuccess: () => void;
};

const mapContainerStyle = {
  width: '100%',
  height: '250px',
  borderRadius: '12px',
  marginTop: '8px',
};

const defaultCenter = {
  lat: 7.8731, // Default to Sri Lanka
  lng: 80.7718
};

// Replace with the user's actual API key in production via process.env.EXPO_PUBLIC_GOOGLE_MAPS_API_KEY
const GOOGLE_MAPS_API_KEY = process.env.EXPO_PUBLIC_GOOGLE_MAPS_API_KEY || '';

export const NewProjectModal = ({ visible, onClose, onSuccess }: NewProjectModalProps) => {
  const [name, setName] = useState('');
  const [location, setLocation] = useState('');
  const [mapSearchQuery, setMapSearchQuery] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [clientEmail, setClientEmail] = useState('');
  const [totalBudget, setTotalBudget] = useState('');
  const [pms, setPms] = useState<any[]>([]);
  const [clients, setClients] = useState<any[]>([]);
  const [siteManagers, setSiteManagers] = useState<any[]>([]);
  const [availableWorkers, setAvailableWorkers] = useState<any[]>([]);
  const [suppliers, setSuppliers] = useState<any[]>([]);
  const [admins, setAdmins] = useState<any[]>([]);
  const [pmId, setPmId] = useState('');
  const [clientId, setClientId] = useState('');
  const [selectedSiteManagers, setSelectedSiteManagers] = useState<string[]>([]);
  const [selectedWorkers, setSelectedWorkers] = useState<string[]>([]);
  const [selectedSuppliers, setSelectedSuppliers] = useState<string[]>([]);
  const [selectedAdmins, setSelectedAdmins] = useState<string[]>([]);
  
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  // Milestones State
  const [milestones, setMilestones] = useState<{ title: string, description: string, due_date: string }[]>([]);

  const addMilestone = () => setMilestones([...milestones, { title: '', description: '', due_date: '' }]);
  
  const updateMilestone = (index: number, field: string, value: string) => {
    const newMilestones = [...milestones];
    newMilestones[index] = { ...newMilestones[index], [field]: value };
    setMilestones(newMilestones);
  };

  const removeMilestone = (index: number) => {
    setMilestones(milestones.filter((_, i) => i !== index));
  };

  // Map state
  const [markerPos, setMarkerPos] = useState<google.maps.LatLngLiteral | null>(null);

  // Load Google Maps Script
  const { isLoaded, loadError } = useLoadScript({
    googleMapsApiKey: GOOGLE_MAPS_API_KEY,
  });

  const typingTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const [pmData, clientData, smData, workerData, supplierData, adminData] = await Promise.all([
          supabase.from('profiles').select('*').in('role', ['pm', 'Project Manager', 'project_manager']),
          supabase.from('profiles').select('*').in('role', ['client', 'Client']),
          supabase.from('profiles').select('*').in('role', ['site_manager', 'Site Manager', 'site manager']),
          supabase.from('profiles').select('*').in('role', ['worker', 'Worker']),
          supabase.from('profiles').select('*').in('role', ['supplier', 'Supplier']),
          supabase.from('profiles').select('*').in('role', ['admin', 'Admin', 'super_admin', 'Super Admin']),
        ]);

        setPms(pmData.data || []);
        setClients(clientData.data || []);
        setSiteManagers(smData.data || []);
        setAvailableWorkers(workerData.data || []);
        setSuppliers(supplierData.data || []);
        setAdmins(adminData.data || []);
      } catch (err) {
        console.error('Failed to fetch users for project assignments', err);
      }
    };

    if (visible) fetchUsers();
  }, [visible]);

  // Store map instance to manually pan
  const [mapInstance, setMapInstance] = useState<google.maps.Map | null>(null);

  const handleSearchMap = async () => {
    if (!mapSearchQuery || !GOOGLE_MAPS_API_KEY) return;
    
    try {
      const response = await fetch(`https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(mapSearchQuery)}&key=${GOOGLE_MAPS_API_KEY}`);
      const data = await response.json();
      
      if (data.status === 'OK' && data.results && data.results.length > 0) {
        const result = data.results[0];
        const loc = result.geometry.location;
        
        setMarkerPos({ lat: loc.lat, lng: loc.lng });
        setLocation(result.formatted_address);
        if (mapInstance) {
          mapInstance.panTo({ lat: loc.lat, lng: loc.lng });
          mapInstance.setZoom(14);
        }
      } else if (data.status === 'REQUEST_DENIED' || data.status === 'OVER_QUERY_LIMIT') {
        console.warn('Google Maps API failed (Billing/Permissions). Falling back to free OpenStreetMap API...');
        
        // Fallback to Free OpenStreetMap (Nominatim) API
        const osmRes = await fetch(`https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(mapSearchQuery)}&format=json&limit=1`);
        const osmData = await osmRes.json();
        
        if (osmData && osmData.length > 0) {
          const loc = { lat: parseFloat(osmData[0].lat), lng: parseFloat(osmData[0].lon) };
          setMarkerPos(loc);
          setLocation(osmData[0].display_name);
          
          if (mapInstance) {
            mapInstance.panTo(loc);
            mapInstance.setZoom(14);
          }
          setErrorMsg(''); // Clear error if fallback succeeds
        } else {
          setErrorMsg('Location not found in OpenStreetMap Fallback either.');
        }
      } else {
        setErrorMsg('Location not found (Status: ' + data.status + ').');
      }
    } catch (e) {
      console.warn('Failed to forward geocode search query', e);
      setErrorMsg('Failed to search map. Check console for details.');
    }
  };

  const onMapClick = useCallback(async (e: google.maps.MapMouseEvent | google.maps.IconMouseEvent) => {
    if (!e.latLng) return;
    
    if ('placeId' in e) {
      e.stop();
    }

    const lat = e.latLng.lat();
    const lng = e.latLng.lng();
    setMarkerPos({ lat, lng });

    // Reverse Geocoding
    if (GOOGLE_MAPS_API_KEY) {
      try {
        const response = await fetch(`https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${GOOGLE_MAPS_API_KEY}`);
        const data = await response.json();
        
        if (data.status === 'OK' && data.results && data.results.length > 0) {
          setLocation(data.results[0].formatted_address);
        } else {
          // Fallback to OpenStreetMap Reverse Geocoding
          const osmRes = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`);
          const osmData = await osmRes.json();
          if (osmData && osmData.display_name) {
            setLocation(osmData.display_name);
          } else {
            setLocation(`Lat: ${lat.toFixed(4)}, Lng: ${lng.toFixed(4)}`);
          }
        }
      } catch (err) {
        setLocation(`Lat: ${lat.toFixed(4)}, Lng: ${lng.toFixed(4)}`);
      }
    } else {
      setLocation(`Lat: ${lat.toFixed(4)}, Lng: ${lng.toFixed(4)}`);
    }
  }, []);

  const handleCreate = async () => {
    if (!name || !location || !startDate || !endDate) {
      setErrorMsg('Please fill in all fields');
      return;
    }

    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!dateRegex.test(startDate) || !dateRegex.test(endDate)) {
      setErrorMsg('Dates must be in YYYY-MM-DD format');
      return;
    }

    setLoading(true);
    setErrorMsg('');

    try {
      let resolvedClientId = clientId;
      if (clientEmail.trim()) {
        const cleanEmail = clientEmail.trim();
        const { data: existingClient, error: clientLookupError } = await supabase
          .from('profiles')
          .select('id, email, full_name')
          .ilike('email', cleanEmail)
          .maybeSingle();

        if (clientLookupError) throw clientLookupError;
        if (existingClient) {
          resolvedClientId = existingClient.id;
          setClientId(existingClient.id);
        }
      }

      const payload = {
        name,
        location,
        address: location,
        status: 'active',
        start_date: startDate,
        end_date: endDate,
        client_id: resolvedClientId || null,
        pm_id: pmId || null,
        site_managers: selectedSiteManagers,
        workers: selectedWorkers,
        suppliers: selectedSuppliers,
        admins: selectedAdmins,
        total_budget: Number(totalBudget) || 0,
        latitude: markerPos?.lat ?? null,
        longitude: markerPos?.lng ?? null,
      };

      const token = (await supabase.auth.getSession()).data.session?.access_token;
      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/projects`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (!response.ok) {
        const err = await response.json().catch(() => ({}));
        throw new Error(err.detail || 'Failed to create project');
      }

      const newProject = await response.json();

      const validMilestones = milestones.filter(m => m.title && m.due_date);
      if (validMilestones.length > 0) {
        const msInserts = validMilestones.map(ms => ({
          project_id: newProject.id,
          title: ms.title,
          description: ms.description,
          due_date: ms.due_date,
          planned_date: ms.due_date,
          status: 'Pending'
        }));
        await supabase.from('milestones').insert(msInserts);
      }

      const notifications: { project_id: string; target_role?: string; target_user_id?: string; title: string; message: string }[] = [
        {
          project_id: newProject.id,
          target_role: 'Project Manager',
          title: 'New Project Created',
          message: `Admin has created a new project: ${name}. Please review the details.`,
        },
      ];

      if (resolvedClientId) {
        notifications.push({
          project_id: newProject.id,
          target_user_id: resolvedClientId,
          title: 'New Project Assigned',
          message: `You have been assigned as the client for ${name}.`,
        });
      }

      if (clientEmail.trim()) {
        await fetch(`${process.env.EXPO_PUBLIC_API_URL}/notifications/email/send`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`,
          },
          body: JSON.stringify({
            to: clientEmail.trim(),
            subject: `New project started: ${name}`,
            html_body: `
              <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
                <div style="background: #F97316; padding: 24px; border-radius: 12px 12px 0 0;">
                  <h1 style="color: white; margin: 0;">ConstructFlow</h1>
                </div>
                <div style="padding: 32px; background: white; border: 1px solid #e5e7eb;">
                  <h2 style="color: #1F2937;">New project started</h2>
                  <p style="color: #6B7280;">A new project has been started for you:</p>
                  <div style="background: #F9FAFB; padding: 16px; border-radius: 8px; margin: 16px 0;">
                    <p style="margin: 4px 0;"><strong>Project:</strong> ${name}</p>
                    <p style="margin: 4px 0;"><strong>Location:</strong> ${location}</p>
                  </div>
                  <p style="color: #6B7280;">Please log in to the client portal to track milestones and project updates.</p>
                </div>
              </div>
            `,
          }),
        });
      }

      await supabase.from('notifications').insert(notifications);

      toast.success('Project created!');

      setName('');
      setLocation('');
      setStartDate('');
      setEndDate('');
      setClientEmail('');
      setTotalBudget('');
      setMarkerPos(null);
      setMilestones([]);
      setPmId('');
      setClientId('');
      setSelectedSiteManagers([]);
      setSelectedWorkers([]);
      setSelectedSuppliers([]);
      setSelectedAdmins([]);
      
      onSuccess();
    } catch (e: any) {
      setErrorMsg(e.message || 'Failed to create project');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal visible={visible} transparent animationType="fade">
      <View className="flex-1 bg-black/50 items-center justify-center p-4">
        <View className="bg-white w-full max-w-2xl rounded-2xl shadow-xl overflow-hidden">
          
          <View className="flex-row justify-between items-center p-6 border-b border-gray-100 bg-brand-light">
            <Text className="text-xl font-bold text-brand-text">Create New Project</Text>
            <Pressable onPress={onClose} className="p-2 rounded-full hover:bg-gray-200 transition-colors">
              <Ionicons name="close" size={24} color="#6B7280" />
            </Pressable>
          </View>

          <ScrollView className="p-6 max-h-[85vh]">
            {errorMsg ? (
              <View className="bg-red-50 p-3 rounded-lg border border-red-200 mb-6">
                <Text className="text-red-600 text-sm text-center">{errorMsg}</Text>
              </View>
            ) : null}

            {!GOOGLE_MAPS_API_KEY && Platform.OS === 'web' && (
               <View className="bg-yellow-50 p-3 rounded-lg border border-yellow-200 mb-6">
                 <Text className="text-yellow-700 text-sm text-center font-semibold">
                   ⚠️ Google Maps API Key is missing. The map will load in development mode and address translation is disabled.
                 </Text>
               </View>
            )}

            <View className="flex-row flex-wrap md:flex-nowrap">
              {/* Left Column: Form Fields */}
              <View className="flex-1 pr-0 md:pr-6 md:border-r border-gray-100 min-w-[250px]">
                <View className="mb-4">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Project Name</Text>
                  <TextInput
                    className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                    placeholder="e.g. Marina Tower"
                    value={name}
                    onChangeText={setName}
                  />
                </View>

                <ProjectAssignmentDropdown
                  label="Assign Project Manager"
                  users={pms}
                  selectedIds={pmId ? [pmId] : []}
                  onChange={(ids) => setPmId(ids[0] || '')}
                />

                <ProjectAssignmentDropdown
                  label="Assign Client"
                  users={clients}
                  selectedIds={clientId ? [clientId] : []}
                  onChange={(ids) => {
                    setClientId(ids[0] || '');
                    const selectedClient = clients.find((user) => user.id === (ids[0] || ''));
                    if (selectedClient?.email) setClientEmail(selectedClient.email);
                  }}
                />

                <ProjectAssignmentDropdown
                  label="Assign Administrators"
                  users={admins}
                  multiple
                  selectedIds={selectedAdmins}
                  onChange={setSelectedAdmins}
                />

                <View className="mb-6">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Start Date</Text>
                  {Platform.OS === 'web' ? (
                    // @ts-ignore
                    <input 
                      type="date"
                      className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors outline-none"
                      value={startDate}
                      onChange={(e) => setStartDate(e.target.value)}
                    />
                  ) : (
                    <TextInput
                      className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                      placeholder="YYYY-MM-DD"
                      value={startDate}
                      onChangeText={setStartDate}
                    />
                  )}
                </View>

                <View className="mb-6">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">End Date</Text>
                  {Platform.OS === 'web' ? (
                    // @ts-ignore
                    <input 
                      type="date"
                      className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors outline-none"
                      value={endDate}
                      onChange={(e) => setEndDate(e.target.value)}
                    />
                  ) : (
                    <TextInput
                      className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                      placeholder="YYYY-MM-DD"
                      value={endDate}
                      onChangeText={setEndDate}
                    />
                  )}
                </View>
                <View className="mb-6">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Total Budget (Rs.)</Text>
                  <TextInput
                    className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                    placeholder="e.g. 5000000"
                    keyboardType="numeric"
                    value={totalBudget}
                    onChangeText={setTotalBudget}
                  />
                </View>

                <ProjectAssignmentDropdown
                  label="Assign Site Managers"
                  users={siteManagers}
                  multiple
                  selectedIds={selectedSiteManagers}
                  onChange={setSelectedSiteManagers}
                />

                <ProjectAssignmentDropdown
                  label="Assign Workers"
                  users={availableWorkers}
                  multiple
                  selectedIds={selectedWorkers}
                  onChange={setSelectedWorkers}
                />

                <ProjectAssignmentDropdown
                  label="Assign Suppliers"
                  users={suppliers}
                  multiple
                  selectedIds={selectedSuppliers}
                  onChange={setSelectedSuppliers}
                />

                <View className="mb-6">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Client Email</Text>
                  <TextInput
                    className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                    placeholder="client@example.com"
                    keyboardType="email-address"
                    value={clientEmail}
                    onChangeText={setClientEmail}
                  />
                </View>
              </View>

              {/* Right Column: Location & Interactive Map */}
              <View className="flex-1 pl-0 md:pl-6 mt-6 md:mt-0 min-w-[250px]">
                <View className="mb-4">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Selected Location Address</Text>
                  <TextInput
                    className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                    placeholder="Exact address will appear here"
                    value={location}
                    onChangeText={setLocation}
                  />
                </View>

                <View className="mb-2">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Search Map</Text>
                  <View className="flex-row gap-2">
                    <TextInput
                      className="flex-1 border border-gray-300 rounded-xl p-3 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                      placeholder="Type city or place name..."
                      value={mapSearchQuery}
                      onChangeText={setMapSearchQuery}
                    />
                    <Pressable
                      onPress={handleSearchMap}
                      className="bg-blue-500 px-4 items-center justify-center rounded-xl hover:bg-blue-600 transition-colors"
                    >
                      <Ionicons name="search" size={20} color="white" />
                    </Pressable>
                  </View>
                  <Text className="text-xs text-gray-400 mt-2">Search for a place and click the button to set it as the location.</Text>
                </View>

                {Platform.OS === 'web' ? (
                  loadError ? (
                    <View className="h-[250px] bg-red-50 rounded-xl mt-2 items-center justify-center border border-red-200">
                      <Text className="text-red-500">Error loading maps</Text>
                    </View>
                  ) : !isLoaded ? (
                    <View className="h-[250px] bg-gray-50 rounded-xl mt-2 items-center justify-center border border-gray-200">
                      <ActivityIndicator color="#F97316" />
                    </View>
                  ) : (
                    <GoogleMap
                      mapContainerStyle={mapContainerStyle}
                      zoom={7}
                      center={markerPos || defaultCenter}
                      onClick={onMapClick}
                      onLoad={setMapInstance}
                      options={{
                        disableDefaultUI: true,
                        zoomControl: true,
                        clickableIcons: false,
                      }}
                    >
                      {markerPos && <Marker position={markerPos} />}
                    </GoogleMap>
                  )
                ) : (
                  <View className="h-[250px] bg-gray-50 rounded-xl mt-2 items-center justify-center border border-gray-200">
                    <Ionicons name="map-outline" size={32} color="#9CA3AF" />
                    <Text className="text-gray-400 mt-2 text-sm text-center px-4">Interactive map is only available on web version.</Text>
                  </View>
                )}
              </View>
            </View>

            {/* Milestones Section */}
            <View className="mt-8 border-t border-gray-100 pt-6">
              <View className="flex-row justify-between items-center mb-4">
                <Text className="text-lg font-bold text-gray-800">Project Milestones</Text>
                <Pressable onPress={addMilestone} className="flex-row items-center bg-gray-100 px-3 py-1.5 rounded-lg">
                  <Ionicons name="add" size={16} color="#4B5563" />
                  <Text className="text-gray-700 font-semibold ml-1 text-sm">Add</Text>
                </Pressable>
              </View>

              {milestones.length === 0 ? (
                <Text className="text-gray-400 italic text-sm">No milestones added yet. You can add them later.</Text>
              ) : (
                milestones.map((ms, index) => (
                  <View key={index} className="bg-gray-50 border border-gray-200 rounded-xl p-4 mb-4">
                    <View className="flex-row justify-between mb-3">
                      <Text className="font-semibold text-gray-700">Milestone {index + 1}</Text>
                      <Pressable onPress={() => removeMilestone(index)}>
                        <Ionicons name="trash-outline" size={18} color="#EF4444" />
                      </Pressable>
                    </View>
                    
                    <View className="flex-row gap-4 mb-3">
                      <View className="flex-[2]">
                        <TextInput 
                          placeholder="Title (e.g. Foundation)" 
                          className="bg-white border border-gray-300 rounded-lg p-3 text-sm"
                          value={ms.title}
                          onChangeText={(t) => updateMilestone(index, 'title', t)}
                        />
                      </View>
                      <View className="flex-1">
                        {Platform.OS === 'web' ? (
                          // @ts-ignore
                          <input 
                            type="date"
                            className="w-full bg-white border border-gray-300 rounded-lg p-3 text-sm outline-none"
                            value={ms.due_date}
                            onChange={(e) => updateMilestone(index, 'due_date', e.target.value)}
                          />
                        ) : (
                          <TextInput 
                            placeholder="YYYY-MM-DD" 
                            className="bg-white border border-gray-300 rounded-lg p-3 text-sm"
                            value={ms.due_date}
                            onChangeText={(t) => updateMilestone(index, 'due_date', t)}
                          />
                        )}
                      </View>
                    </View>
                    
                    <TextInput 
                      placeholder="Description (Optional)" 
                      className="bg-white border border-gray-300 rounded-lg p-3 text-sm"
                      value={ms.description}
                      onChangeText={(t) => updateMilestone(index, 'description', t)}
                    />
                  </View>
                ))
              )}
            </View>

            <View className="flex-row gap-4 pt-6 border-t border-gray-100 mt-6">
              <Pressable 
                onPress={onClose}
                disabled={loading}
                className="flex-1 bg-gray-100 py-4 rounded-xl items-center justify-center hover:bg-gray-200 transition-colors"
              >
                <Text className="text-gray-600 font-bold text-base">Cancel</Text>
              </Pressable>
              <Pressable 
                onPress={handleCreate}
                disabled={loading}
                className={`flex-1 bg-brand-orange py-4 rounded-xl items-center justify-center shadow-sm hover:bg-orange-600 transition-colors ${loading ? 'opacity-70' : ''}`}
              >
                {loading ? (
                  <ActivityIndicator color="white" />
                ) : (
                  <Text className="text-white font-bold text-base">Create Project</Text>
                )}
              </Pressable>
            </View>
          </ScrollView>

        </View>
      </View>
    </Modal>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, Pressable, ActivityIndicator } from 'react-native';
import { supabase } from '../../lib/supabase';
import { useRouter } from 'expo-router';

const AlertItem = ({ title, subtext, iconColor }: { title: string, subtext: string, iconColor: string }) => {
  return (
    <View className="flex-row items-start mb-4">
      {/* Icon Placeholder */}
      <View className={`w-8 h-8 rounded-full items-center justify-center mr-3 mt-0.5 ${iconColor.replace('text-', 'bg-').replace('-500', '-100')}`}>
         <View className={`w-3 h-3 rounded-sm ${iconColor.replace('text-', 'bg-')}`} />
      </View>
      
      {/* Content */}
      <View className="flex-1">
        <Text className="text-brand-text font-bold text-sm mb-0.5">{title}</Text>
        <Text className="text-gray-500 text-xs">{subtext}</Text>
      </View>
    </View>
  );
};

export const RecentAlertsPanel = ({ pmId }: { pmId?: string }) => {
  const [alerts, setAlerts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();

  useEffect(() => {
    let isMounted = true;
    
    const loadAlerts = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        let query = supabase
          .from('notifications')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(4);
          
        if (pmId) {
          query = query.or(`target_user_id.eq.${pmId},target_role.eq.Manager`);
        }

        const { data, error } = await query;

        if (error) throw error;
        
        if (isMounted) setAlerts(data || []);
      } catch (error) {
        console.warn('Failed to load alerts:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadAlerts();

    // Supabase Realtime subscribe
    const channel = supabase
      .channel('dashboard_alerts')
      .on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'notifications'
      }, (payload) => {
        if (isMounted) {
          setAlerts(prev => [payload.new, ...prev].slice(0, 4));
        }
      })
      .subscribe();
    
    return () => { 
      isMounted = false; 
      supabase.removeChannel(channel);
    };
  }, []);

  const getIconColor = (type: string) => {
    switch(type) {
      case 'Alert': return 'text-brand-orange';
      case 'Warning': return 'text-brand-danger'; // fallback if warning
      case 'Success': return 'text-brand-success';
      case 'Info':
      default: return 'text-blue-500';
    }
  };

  const getTimeAgo = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInMinutes = Math.floor((now.getTime() - date.getTime()) / 60000);
    
    if (diffInMinutes < 60) return `${diffInMinutes} mins ago`;
    const diffInHours = Math.floor(diffInMinutes / 60);
    if (diffInHours < 24) return `${diffInHours} hr${diffInHours > 1 ? 's' : ''} ago`;
    return date.toLocaleDateString();
  };

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 min-h-[300px]">
      <View className="flex-row justify-between items-center mb-6">
        <Text className="text-lg font-bold text-brand-text">Recent Alerts</Text>
        {alerts.filter(a => a.is_unread).length > 0 && (
          <View className="bg-brand-orange px-2 py-1 rounded-full">
            <Text className="text-white text-[10px] font-bold">{alerts.filter(a => a.is_unread).length} new</Text>
          </View>
        )}
      </View>

      <View className="flex-1">
        {loading ? (
          <View className="flex-1 justify-center items-center">
            <ActivityIndicator color="#F97316" />
          </View>
        ) : alerts.length === 0 ? (
          <View className="flex-1 justify-center items-center">
            <Text className="text-gray-400">No new alerts.</Text>
          </View>
        ) : (
          alerts.map(a => (
            <AlertItem 
              key={a.id}
              title={a.title} 
              subtext={getTimeAgo(a.created_at)} 
              iconColor={getIconColor(a.type)} 
            />
          ))
        )}
      </View>

      <Pressable 
        className="mt-auto pt-4 border-t border-gray-50 items-center"
        onPress={() => router.push('/admin/notifications')}
      >
        <Text className="text-brand-orange text-sm font-semibold">View all notifications →</Text>
      </Pressable>
    </View>
  );
};

import React, { useState } from 'react';
import { View, Text, TextInput, Pressable, ActivityIndicator, Alert } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { supabase } from '../../lib/supabase';
import { api } from '../../lib/api';
import { toast } from '../../lib/toast';

export const QuotationForm = ({ onEstimateCreated = () => {} }: { onEstimateCreated?: () => void }) => {
  const [projectType, setProjectType] = useState('Residential');
  const [squareFootage, setSquareFootage] = useState('');
  const [location, setLocation] = useState('Colombo');
  const [qualityTier, setQualityTier] = useState('Standard');
  const [isGenerating, setIsGenerating] = useState(false);

  const cycleOption = (current: string, options: string[], setter: (v: string) => void) => {
    const idx = options.indexOf(current);
    setter(options[(idx + 1) % options.length]);
  };

  const handleGenerate = async () => {
    if (!squareFootage || !Number.isFinite(Number(squareFootage)) || Number(squareFootage) <= 0) {
      toast.error('Please enter a valid square footage.');
      return;
    }

    setIsGenerating(true);

    try {
      const { data: sessionData } = await supabase.auth.getSession();
      if (!sessionData?.session) throw new Error('Not logged in');

      // Map location to location_index
      const locMap: Record<string, number> = { 'Colombo': 1.5, 'Kandy': 1.1, 'Galle': 1.2, 'Other': 0.9 };
      const location_index = locMap[location] || 1.0;

      // Call via standardized API interface as per prompt
      const aiData = await api.post('/estimations/predict', {
        project_name: `${projectType} in ${location}`,
        square_footage: Number(squareFootage),
        num_floors: projectType === 'Commercial' ? 4 : projectType === 'Industrial' ? 2 : 1,
        material_quality: qualityTier,
        location_index: location_index
      });

      const estimatedCost = aiData.estimated_cost;
      const confidence = aiData.confidence_score;

      toast.success(`AI Estimate Generated: Rs. ${(estimatedCost / 1000000).toFixed(2)}M\nConfidence: ${confidence == null ? 'Not validated (synthetic prototype)' : `${confidence}%`}`);
      setSquareFootage('');
      onEstimateCreated();
    } catch (error: any) {
      toast.error(error.message || 'Failed to generate estimate');
    } finally {
      setIsGenerating(false);
    }
  };
  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 mb-6">
      <View className="flex-row justify-between items-start mb-6">
        <View>
          <Text className="text-lg font-bold text-brand-text mb-1">Project Estimate Generator</Text>
          <Text className="text-brand-text-muted text-xs">Configure parameters for the AI model</Text>
        </View>
        <View className="flex-row items-center bg-orange-100 px-3 py-1.5 rounded-full">
          <Ionicons name="flash" size={14} color="#F97316" className="mr-1" />
          <Text className="text-brand-orange text-xs font-bold">AI Assisted</Text>
        </View>
      </View>

      <View className="flex-row flex-wrap -mx-3">
        <View className="w-full md:w-1/2 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Project Type</Text>
          <Pressable 
            onPress={() => cycleOption(projectType, ['Residential', 'Commercial', 'Industrial'], setProjectType)}
            className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center"
          >
            <Text className="text-brand-text text-sm">{projectType}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>

        <View className="w-full md:w-1/2 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Square Footage (sq.ft)</Text>
          <View className="border border-gray-200 rounded-lg px-4 py-2.5">
            <TextInput 
              placeholder="e.g. 2400"
              placeholderTextColor="#9CA3AF"
              className="text-brand-text text-sm"
              keyboardType="numeric"
              value={squareFootage}
              onChangeText={setSquareFootage}
            />
          </View>
        </View>

        <View className="w-full md:w-1/2 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Location</Text>
          <Pressable 
            onPress={() => cycleOption(location, ['Colombo', 'Kandy', 'Galle', 'Other'], setLocation)}
            className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center"
          >
            <Text className="text-brand-text text-sm">{location}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>

        <View className="w-full md:w-1/2 px-3 mb-4">
          <Text className="text-gray-500 text-xs font-semibold mb-2">Quality Tier</Text>
          <Pressable 
            onPress={() => cycleOption(qualityTier, ['Standard', 'Premium', 'Luxury'], setQualityTier)}
            className="border border-gray-200 rounded-lg bg-gray-50 px-4 py-3 flex-row justify-between items-center"
          >
            <Text className="text-brand-text text-sm">{qualityTier}</Text>
            <Ionicons name="swap-vertical" size={16} color="#9CA3AF" />
          </Pressable>
        </View>
      </View>

      <View className="flex-row justify-end mt-2">
        <Pressable 
          onPress={handleGenerate}
          disabled={isGenerating}
          className={`px-6 py-3 rounded-lg flex-row items-center ${isGenerating ? 'bg-gray-400' : 'bg-brand-orange'}`}
        >
          {isGenerating ? (
            <ActivityIndicator size="small" color="#ffffff" className="mr-2" />
          ) : (
            <Ionicons name="settings-sharp" size={16} color="#ffffff" className="mr-2" />
          )}
          <Text className="text-white font-semibold text-sm">
            {isGenerating ? 'Generating...' : 'Generate Estimate'}
          </Text>
        </Pressable>
      </View>
    </View>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, ScrollView, ActivityIndicator } from 'react-native';
import { supabase } from '../../lib/supabase';
import { useResponsive } from '../../hooks/useResponsive';
import { Ionicons } from '@expo/vector-icons';

const AttendanceRow = ({ 
  name, 
  role, 
  project, 
  checkIn, 
  hours, 
  status 
}: { 
  name: string, 
  role: string, 
  project: string, 
  checkIn: string, 
  hours: string | number, 
  status: 'Present' | 'Absent' | 'On Leave' 
}) => {
  const { isMobile } = useResponsive();

  if (isMobile) {
    const getMobileStatusColor = () => {
      if (status === 'Present') return { bg: '#D1FAE5', text: '#065F46' };
      if (status === 'Absent') return { bg: '#FEE2E2', text: '#991B1B' };
      return { bg: '#FEF9C3', text: '#A16207' };
    };
    const mobileStatus = getMobileStatusColor();
    const initials = name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase() || '?';

    return (
      <View style={{ backgroundColor: '#fff', borderRadius: 12, borderWidth: 0.5, borderColor: '#E5E7EB', padding: 12, marginBottom: 12 }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12, marginBottom: 12 }}>
          <View style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: '#EFF6FF', justifyContent: 'center', alignItems: 'center' }}>
            <Text style={{ color: '#1D4ED8', fontWeight: 'bold', fontSize: 16 }}>{initials}</Text>
          </View>
          <View style={{ flex: 1 }}>
            <Text style={{ fontSize: 15, fontWeight: '700', color: '#111827' }} numberOfLines={1} ellipsizeMode="tail">
              {name}
            </Text>
            <Text style={{ fontSize: 12, color: '#6B7280' }} numberOfLines={1} ellipsizeMode="tail">
              {role}
            </Text>
          </View>
          <View style={{ backgroundColor: mobileStatus.bg, paddingHorizontal: 8, paddingVertical: 4, borderRadius: 12 }}>
            <Text style={{ color: mobileStatus.text, fontSize: 10, fontWeight: 'bold', textTransform: 'uppercase' }}>
              {status}
            </Text>
          </View>
        </View>

        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
            <Ionicons name="location-outline" size={14} color="#6B7280" />
            <Text style={{ fontSize: 13, color: '#6B7280' }}>{project}</Text>
          </View>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
              <Ionicons name="log-in-outline" size={14} color="#6B7280" />
              <Text style={{ fontSize: 13, color: '#6B7280' }}>{checkIn}</Text>
            </View>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
              <Ionicons name="time-outline" size={14} color="#6B7280" />
              <Text style={{ fontSize: 13, color: '#6B7280' }}>{hours}h</Text>
            </View>
          </View>
        </View>
      </View>
    );
  }
  
  let statusBadgeColor = '';
  let statusTextColor = '';

  switch (status) {
    case 'Present':
      statusBadgeColor = 'bg-[#DCFCE7]';
      statusTextColor = 'text-brand-success';
      break;
    case 'Absent':
      statusBadgeColor = 'bg-[#FEE2E2]';
      statusTextColor = 'text-brand-danger';
      break;
    case 'On Leave':
      statusBadgeColor = 'bg-[#FEF9C3]'; // yellow-100
      statusTextColor = 'text-[#A16207]'; // yellow-700
      break;
  }
  
  return (
    <View className="flex-row items-center py-4 border-b border-gray-100">
      {/* Worker Name & Role */}
      <View className="w-1/4">
        <Text className="text-brand-text font-semibold text-sm">{name}</Text>
        <Text className="text-gray-500 text-xs">{role}</Text>
      </View>

      {/* Project/Site */}
      <View className="w-1/4">
        <Text className="text-brand-text text-sm">{project}</Text>
      </View>

      {/* Check-in Time */}
      <View className="w-1/6">
        <Text className="text-gray-600 text-sm">{checkIn}</Text>
      </View>

      {/* Hours Worked */}
      <View className="w-1/6">
        <Text className="text-brand-text text-sm font-medium">{hours}</Text>
      </View>

      {/* Status Badge */}
      <View className="flex-1 flex-row justify-end">
        <View className={`${statusBadgeColor} px-2 py-1 rounded`}>
          <Text className={`${statusTextColor} text-xs font-semibold`}>{status}</Text>
        </View>
      </View>
    </View>
  );
};

export const AttendanceTable = ({ refreshTrigger = 0, searchQuery = '', pmId }: { refreshTrigger?: number, searchQuery?: string, pmId?: string }) => {
  const { isMobile } = useResponsive();
  const [labour, setLabour] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    
    const loadLabour = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        const today = new Date().toISOString().split('T')[0];

        // Fetch attendance for today from labour table
        let query = supabase
          .from('labour')
          .select(`
            id, check_in_time, hours_worked, status, worker_name, role,
            project:projects!inner(name, pm_id)
          `)
          .eq('date', today)
          .order('check_in_time', { ascending: false });

        if (pmId) {
          query = query.eq('project.pm_id', pmId);
        }

        const { data, error } = await query;
        if (error) throw error;
        
        if (isMounted) setLabour(data || []);
      } catch (error) {
        console.warn('Failed to load attendance:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadLabour();
    
    return () => { isMounted = false; };
  }, [refreshTrigger, pmId]);

  const filteredLabour = labour.filter(item => {
    if (!searchQuery) return true;
    const s = searchQuery.toLowerCase();
    const workerName = item.worker_name?.toLowerCase() || '';
    const projectName = item.project?.name?.toLowerCase() || '';
    return workerName.includes(s) || projectName.includes(s);
  });
  const formatTime = (isoString: string) => {
    if (!isoString) return '—';
    const date = new Date(isoString);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 min-h-[400px]">
      <View className="mb-6">
        <Text className="text-lg font-bold text-brand-text mb-1">Worker Attendance</Text>
        <Text className="text-brand-text-muted text-xs">Daily check-in status across sites</Text>
      </View>

      {/* Table Header */}
      {!isMobile && (
        <View className="flex-row py-3 border-b border-gray-200">
          <Text className="w-1/4 text-xs font-semibold text-gray-500 uppercase">Worker</Text>
          <Text className="w-1/4 text-xs font-semibold text-gray-500 uppercase">Project / Site</Text>
          <Text className="w-1/6 text-xs font-semibold text-gray-500 uppercase">Check-in</Text>
          <Text className="w-1/6 text-xs font-semibold text-gray-500 uppercase">Hours</Text>
          <Text className="w-1/6 text-xs font-semibold text-gray-500 uppercase text-right pr-2">Status</Text>
        </View>
      )}

      {loading ? (
        <View className="flex-1 items-center justify-center py-10">
          <ActivityIndicator size="large" color="#3B82F6" />
        </View>
      ) : (
        <ScrollView showsVerticalScrollIndicator={false}>
          {filteredLabour.length === 0 ? (
            <View className="py-10 items-center">
              <Text className="text-gray-400">No workers found.</Text>
            </View>
          ) : (
            filteredLabour.map(l => {
              const pName = l.project?.name || 'Unknown Site';
              
              // Format check-in time
              let checkInFormatted = '--:--';
              if (l.check_in_time) {
                const dt = new Date(l.check_in_time);
                const hh = String(dt.getHours()).padStart(2, '0');
                const mm = String(dt.getMinutes()).padStart(2, '0');
                checkInFormatted = `${hh}:${mm}`;
              } else if (l.status === 'Absent' || l.status === 'On Leave') {
                checkInFormatted = l.status;
              }

              return (
                <AttendanceRow 
                  key={l.id}
                  name={l.worker_name || 'Unknown'} 
                  role={l.role || 'Worker'} 
                  project={pName} 
                  checkIn={checkInFormatted} 
                  hours={l.hours_worked || 0} 
                  status={l.status as any} 
                />
              );
            })
          )}
        </ScrollView>
      )}
    </View>
  );
};

import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Pressable, ActivityIndicator, Modal, ScrollView, Platform } from 'react-native';
import { supabase } from '../../lib/supabase';
import { api } from '../../lib/api';
import { Ionicons } from '@expo/vector-icons';
import { toast } from '../../lib/toast';

type CheckInWorkerModalProps = {
  visible: boolean;
  onClose: () => void;
  onSuccess: () => void;
};

export const CheckInWorkerModal = ({ visible, onClose, onSuccess }: CheckInWorkerModalProps) => {
  const [workerId, setWorkerId] = useState<string | null>(null);
  const [projectId, setProjectId] = useState<string | null>(null);
  const [status, setStatus] = useState<'Present' | 'On Leave' | 'Absent'>('Present');
  const [checkInTime, setCheckInTime] = useState('');
  const [hoursWorked, setHoursWorked] = useState('8');
  const [overtime, setOvertime] = useState('0');
  
  const [workers, setWorkers] = useState<any[]>([]);
  const [projects, setProjects] = useState<any[]>([]);
  
  const [loading, setLoading] = useState(false);
  const [fetchingData, setFetchingData] = useState(true);
  const [errorMsg, setErrorMsg] = useState('');

  // Fetch active projects and workers
  useEffect(() => {
    if (!visible) return;

    let isMounted = true;
    const fetchData = async () => {
      setFetchingData(true);
      try {
        const [projectsReq, workersReq] = await Promise.all([
          supabase.from('projects').select('id, name').eq('status', 'Active'),
          supabase.from('profiles').select('id, full_name').eq('role', 'worker')
        ]);
        
        if (projectsReq.error) throw projectsReq.error;
        if (workersReq.error) throw workersReq.error;
        
        if (isMounted) {
          setProjects(projectsReq.data || []);
          setWorkers(workersReq.data || []);
          
          // Auto-set time to now in HH:mm format
          const now = new Date();
          const hh = String(now.getHours()).padStart(2, '0');
          const mm = String(now.getMinutes()).padStart(2, '0');
          setCheckInTime(`${hh}:${mm}`);
        }
      } catch (err) {
        console.warn('Could not load lookup data for check-in modal', err);
      } finally {
        if (isMounted) setFetchingData(false);
      }
    };
    fetchData();
    return () => { isMounted = false; };
  }, [visible]);

  const handleCreate = async () => {
    if (!workerId || !projectId || !status) {
      setErrorMsg('Please select a worker, project, and status.');
      return;
    }
    if (status === 'Present' && !checkInTime) {
      setErrorMsg('Check in time is required when Present.');
      return;
    }

    setLoading(true);
    setErrorMsg('');

    try {
      const selectedWorker = workers.find(w => w.id === workerId);
      const workerName = selectedWorker ? selectedWorker.full_name : 'Unknown Worker';
      
      const now = new Date();
      // Format checkInTime to a full timestamp if they are present
      let checkInTimestamp = null;
      if (status === 'Present' && checkInTime) {
        const [hh, mm] = checkInTime.split(':');
        const dt = new Date();
        dt.setHours(Number(hh), Number(mm), 0, 0);
        checkInTimestamp = dt.toISOString();
      }

      const totalHours = status === 'Present' ? Number(hoursWorked) + Number(overtime) : 0;

      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData?.session?.access_token;
      
      const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/labour`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          project_id: projectId,
          worker_name: workerName,
          role: 'Labourer',
          hours_worked: totalHours,
          status: status
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Failed to record attendance');
      }

      // Reset form
      setWorkerId(null);
      setProjectId(null);
      setStatus('Present');
      setHoursWorked('8');
      setOvertime('0');
      
      toast.success('Attendance recorded!');
      onSuccess();
    } catch (e: any) {
      setErrorMsg(e.message || 'Failed to record attendance');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal visible={visible} transparent animationType="fade">
      <View className="flex-1 bg-black/50 items-center justify-center p-4">
        <View className="bg-white w-full max-w-lg rounded-2xl shadow-xl overflow-hidden">
          
          {/* Header */}
          <View className="flex-row justify-between items-center p-6 border-b border-gray-100 bg-brand-light">
            <Text className="text-xl font-bold text-brand-text">Check In Worker</Text>
            <Pressable onPress={onClose} className="p-2 rounded-full hover:bg-gray-200 transition-colors">
              <Ionicons name="close" size={24} color="#6B7280" />
            </Pressable>
          </View>

          <ScrollView className="p-6 max-h-[70vh]">
            {errorMsg ? (
              <View className="bg-red-50 p-3 rounded-lg border border-red-200 mb-6">
                <Text className="text-red-600 text-sm text-center">{errorMsg}</Text>
              </View>
            ) : null}

            {fetchingData ? (
              <View className="py-10 items-center justify-center">
                <ActivityIndicator color="#F97316" />
              </View>
            ) : (
              <>
                <View className="mb-4">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Select Worker</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row gap-2">
                    {workers.map(w => (
                      <Pressable
                        key={w.id}
                        onPress={() => setWorkerId(w.id)}
                        className={`px-4 py-2 rounded-full border ${workerId === w.id ? 'bg-brand-orange border-brand-orange' : 'bg-gray-50 border-gray-200'}`}
                      >
                        <Text className={`text-sm font-semibold ${workerId === w.id ? 'text-white' : 'text-gray-600'}`}>
                          {w.full_name}
                        </Text>
                      </Pressable>
                    ))}
                    {workers.length === 0 && (
                       <Text className="text-gray-400 text-sm italic">No active workers found.</Text>
                    )}
                  </ScrollView>
                </View>

                <View className="mb-4">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Assign to Project</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false} className="flex-row gap-2">
                    {projects.map(p => (
                      <Pressable
                        key={p.id}
                        onPress={() => setProjectId(p.id)}
                        className={`px-4 py-2 rounded-full border ${projectId === p.id ? 'bg-brand-orange border-brand-orange' : 'bg-gray-50 border-gray-200'}`}
                      >
                        <Text className={`text-sm font-semibold ${projectId === p.id ? 'text-white' : 'text-gray-600'}`}>
                          {p.name}
                        </Text>
                      </Pressable>
                    ))}
                    {projects.length === 0 && (
                       <Text className="text-gray-400 text-sm italic">No active projects found.</Text>
                    )}
                  </ScrollView>
                </View>

                <View className="mb-4">
                  <Text className="text-sm font-semibold text-gray-700 mb-2">Status</Text>
                  <View className="flex-row gap-2">
                    {['Present', 'On Leave', 'Absent'].map(s => (
                      <Pressable
                        key={s}
                        onPress={() => setStatus(s as any)}
                        className={`flex-1 py-3 rounded-xl border items-center justify-center ${status === s ? 'bg-brand-dark border-brand-dark' : 'bg-gray-50 border-gray-200'}`}
                      >
                        <Text className={`text-sm font-semibold ${status === s ? 'text-white' : 'text-gray-600'}`}>
                          {s}
                        </Text>
                      </Pressable>
                    ))}
                  </View>
                </View>

                {status === 'Present' && (
                  <>
                    <View className="mb-4">
                      <Text className="text-sm font-semibold text-gray-700 mb-2">Check In Time</Text>
                      {Platform.OS === 'web' ? (
                        // @ts-ignore
                        <input 
                          type="time"
                          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors outline-none"
                          value={checkInTime}
                          onChange={(e) => setCheckInTime(e.target.value)}
                        />
                      ) : (
                        <TextInput
                          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                          placeholder="HH:mm"
                          value={checkInTime}
                          onChangeText={setCheckInTime}
                        />
                      )}
                    </View>

                    <View className="flex-row gap-4 mb-4">
                      <View className="flex-1">
                        <Text className="text-sm font-semibold text-gray-700 mb-2">Hours Worked</Text>
                        <TextInput
                          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                          placeholder="8"
                          keyboardType="numeric"
                          value={hoursWorked}
                          onChangeText={setHoursWorked}
                        />
                      </View>
                      <View className="flex-1">
                        <Text className="text-sm font-semibold text-gray-700 mb-2">Overtime (hrs)</Text>
                        <TextInput
                          className="w-full border border-gray-300 rounded-xl p-4 text-brand-text bg-gray-50 focus:border-brand-orange focus:bg-white transition-colors"
                          placeholder="0"
                          keyboardType="numeric"
                          value={overtime}
                          onChangeText={setOvertime}
                        />
                      </View>
                    </View>
                  </>
                )}
              </>
            )}

            {/* Footer Buttons */}
            <View className="flex-row gap-4 pt-4 border-t border-gray-100 pb-2">
              <Pressable 
                onPress={onClose}
                disabled={loading}
                className="flex-1 bg-gray-100 py-4 rounded-xl items-center justify-center hover:bg-gray-200 transition-colors"
              >
                <Text className="text-gray-600 font-bold text-base">Cancel</Text>
              </Pressable>
              <Pressable 
                onPress={handleCreate}
                disabled={loading || fetchingData}
                className={`flex-1 bg-brand-orange py-4 rounded-xl items-center justify-center shadow-sm hover:bg-orange-600 transition-colors ${loading || fetchingData ? 'opacity-70' : ''}`}
              >
                {loading ? (
                  <ActivityIndicator color="white" />
                ) : (
                  <Text className="text-white font-bold text-base">Check In</Text>
                )}
              </Pressable>
            </View>
          </ScrollView>

        </View>
      </View>
    </Modal>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, ActivityIndicator } from 'react-native';
import { supabase } from '../../lib/supabase';

const Bar = ({ label, percentage, count }: { label: string, percentage: number, count: number }) => (
  <View className="items-center justify-end flex-1 mx-2 h-full">
    {/* Label at top */}
    <Text className="text-brand-text font-semibold text-xs mb-1">{count}</Text>
    
    {/* The Bar */}
    <View 
      className="w-full bg-brand-orange rounded-t-sm" 
      style={{ height: `${percentage}%`, minHeight: '5%' }} 
    />
    
    {/* X-axis Label */}
    <Text className="text-gray-500 text-[10px] text-center mt-2 h-8 leading-tight">
      {label}
    </Text>
  </View>
);

export const LabourDistributionChart = ({ refreshTrigger = 0, pmId }: { refreshTrigger?: number, pmId?: string }) => {
  const [data, setData] = useState<{label: string, count: number}[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    
    const loadData = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        // Fetch all active projects
        let query = supabase.from('projects').select('id, name').eq('status', 'Active');
        if (pmId) {
          query = query.eq('pm_id', pmId);
        }
        const { data: projects } = await query;
        
        // Fetch all attendance for today
        const today = new Date().toISOString().split('T')[0];
        const { data: todayLabour } = await supabase.from('labour').select('project_id, worker_name').eq('date', today);
        
        if (projects && todayLabour) {
          const counts = projects.map(p => {
            const count = todayLabour.filter(l => l.project_id === p.id).length;
            return { label: p.name, count };
          });
          
          if (isMounted) setData(counts);
        }
      } catch (error) {
        console.warn('Failed to load chart data:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadData();
    return () => { isMounted = false; };
  }, [refreshTrigger]);

  const maxCount = Math.max(...data.map(d => d.count), 1); // Avoid division by zero

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1">
      <View className="mb-4">
        <Text className="text-lg font-bold text-brand-text">Labour Distribution</Text>
        <Text className="text-brand-text-muted text-xs">Total assigned workers per project site</Text>
      </View>

      <View className="flex-1 flex-row items-end justify-around pt-4 pb-2 border-b border-gray-100">
        {loading ? (
          <ActivityIndicator color="#F97316" className="self-center flex-1" />
        ) : data.length === 0 ? (
          <Text className="text-gray-400 self-center flex-1 text-center">No projects.</Text>
        ) : (
          data.slice(0, 4).map((d, i) => (
            <Bar key={i} label={d.label} count={d.count} percentage={(d.count / maxCount) * 90} />
          ))
        )}
      </View>
    </View>
  );
};

import React, { useEffect, useState } from 'react';
import { View, Text, Pressable, ActivityIndicator, Alert } from 'react-native';
import { supabase } from '../../lib/supabase';

const PayrollRow = ({ name, role, total }: { name: string, role: string, total: number }) => (
  <View className="flex-row justify-between items-center py-2 border-b border-gray-50">
    <View className="w-2/3">
      <Text className="text-gray-600 text-sm truncate" numberOfLines={1}>{name}</Text>
      <Text className="text-gray-400 text-xs">{role}</Text>
    </View>
    <Text className="text-brand-text font-semibold text-sm">
      {total >= 1000 ? `Rs. ${(total/1000).toFixed(1)}K` : `Rs. ${total.toFixed(0)}`}
    </Text>
  </View>
);

export const PayrollSummary = ({ refreshTrigger = 0, pmId }: { refreshTrigger?: number, pmId?: string }) => {
  const [data, setData] = useState<{name: string, role: string, total: number}[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;
    
    const loadPayroll = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session) {
          if (isMounted) setLoading(false);
          return;
        }

        const today = new Date().toISOString().split('T')[0];
        
        // Fetch attendance from backend API
        const response = await fetch(`${process.env.EXPO_PUBLIC_API_URL}/labour/payroll`, {
          headers: {
            'Authorization': `Bearer ${sessionData.session.access_token}`
          }
        });
        
        if (!response.ok) {
          throw new Error('Failed to fetch payroll data');
        }
        
        const attendance = await response.json();
        
        if (attendance) {
          // Filter by pmId if provided (the backend could ideally do this, but doing it here for now)
          // The backend payroll response might need to include pm_id if we want to filter on frontend, 
          // but since this is an admin dashboard, we can just show all for now or filter if the backend provides it.
          const payrolls = attendance.map((a: any) => {
            const dailyRate = 3500; // Default daily wage
            const hourlyRate = dailyRate / 8;
            
            const hours = Number(a.total_hours) || 0;
            const baseHours = Math.min(hours, 8 * a.days_present);
            const overtimeHours = Math.max(0, hours - (8 * a.days_present));
            
            const basePay = baseHours * hourlyRate;
            const overtimePay = overtimeHours * hourlyRate * 1.5;
            const total = basePay + overtimePay;
            
            return {
              name: a.worker_name || 'Unknown',
              role: a.role || 'Worker',
              total
            };
          });
          
          if (isMounted) {
            const activePayrolls = payrolls.filter((p: any) => p.total > 0).sort((a: any, b: any) => b.total - a.total);
            setData(activePayrolls);
          }
        }
      } catch (error) {
        console.warn('Failed to load payroll data:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadPayroll();
    return () => { isMounted = false; };
  }, [refreshTrigger]);

  const totalAmount = data.reduce((sum, item) => sum + item.total, 0);

  const formatCurrency = (val: number) => {
    if (val >= 1000000) return `Rs. ${(val / 1000000).toFixed(1)}M`;
    if (val >= 1000) return `Rs. ${(val / 1000).toFixed(1)}K`;
    return `Rs. ${val}`;
  };

  const handleApprove = () => {
    if (totalAmount === 0) {
      Alert.alert("No Payroll", "There are no workers checked in today to approve payroll for.");
    } else {
      Alert.alert("Payroll Approved", `Successfully approved ${formatCurrency(totalAmount)} for ${data.length} workers.`);
    }
  };

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 mb-6">
      <View className="mb-4">
        <Text className="text-lg font-bold text-brand-text">Payroll Summary</Text>
        <Text className="text-brand-text-muted text-xs">Estimated daily wages by worker</Text>
      </View>

      <View className="mb-2 min-h-[100px]">
        {loading ? (
          <ActivityIndicator color="#F97316" className="mt-4" />
        ) : data.length === 0 || totalAmount === 0 ? (
          <Text className="text-gray-400 text-sm mt-4 text-center">No active workers today.</Text>
        ) : (
          data.slice(0, 4).map((d, i) => (
            <PayrollRow key={i} name={d.name} role={d.role} total={d.total} />
          ))
        )}
      </View>
      
      <View className="flex-row justify-between items-center py-3 border-t border-gray-200 mb-4 mt-auto">
        <Text className="text-brand-text font-bold text-base">Total Pending</Text>
        <Text className="text-brand-text font-bold text-base">{formatCurrency(totalAmount)}</Text>
      </View>

      <Pressable 
        onPress={handleApprove}
        className="bg-brand-orange w-full py-3 rounded-lg items-center justify-center hover:bg-orange-600 transition-colors"
      >
        <Text className="text-white font-semibold text-sm">Approve Payroll</Text>
      </Pressable>
    </View>
  );
};

