import { useAuth } from '../../context/AuthContext';

const SuggestModal = ({ visible, order, onClose, onSubmit }: any) => {
  const [qty, setQty] = useState('');
  const [date, setDate] = useState('');
  const [notes, setNotes] = useState('');

  useEffect(() => {
    if (order) {
      setQty(order.quantity_ordered?.toString() || '');
      setDate(order.expected_date || '');
      setNotes('');
    }
  }, [order]);

  if (!visible || !order) return null;

  return (
    <Modal visible={visible} transparent animationType="fade">
      <View className="flex-1 bg-black/50 justify-center items-center p-4">
        <View className="bg-white rounded-2xl w-full max-w-md p-6">
          <Text className="text-xl font-bold text-brand-text mb-4">Counter-Offer Suggestion</Text>
          <Text className="text-gray-500 mb-4 text-sm">Propose a different quantity or delivery date for PO {order.po_number}.</Text>

          <Text className="font-semibold text-gray-700 mb-1">Suggested Quantity</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-4 text-brand-text"
            keyboardType="numeric"
            value={qty}
            onChangeText={setQty}
          />

          <Text className="font-semibold text-gray-700 mb-1">Suggested Date (YYYY-MM-DD)</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-4 text-brand-text"
            value={date}
            onChangeText={setDate}
          />

          <Text className="font-semibold text-gray-700 mb-1">Notes to Admin</Text>
          <TextInput 
            className="border border-gray-300 rounded-lg p-3 mb-6 text-brand-text h-20"
            multiline
            value={notes}
            onChangeText={setNotes}
          />

          <View className="flex-row justify-end space-x-3">
            <Pressable onPress={onClose} className="px-4 py-2">
              <Text className="text-gray-500 font-bold">Cancel</Text>
            </Pressable>
            <Pressable 
              onPress={() => onSubmit(order.id, parseFloat(qty), date, notes)} 
              className="bg-brand-warning px-6 py-2 rounded-lg"
            >
              <Text className="text-white font-bold">Submit Suggestion</Text>
            </Pressable>
          </View>
        </View>
      </View>
    </Modal>
  );
};

const OrderRow = ({ order, onApprove, onReject, onSuggestClick, isMobile }: any) => {
  const projectName = order.projects?.name || 'Unknown Project';
  const isPending = order.status === 'Pending Delivery';
  const isConfirmed = order.status === 'Confirmed';
  const isRejected = order.status === 'Rejected';
  const isSuggested = order.status === 'Suggested';
  
  const getStatusColor = () => {
    if (isPending) return 'bg-orange-100 text-brand-warning';
    if (isConfirmed) return 'bg-blue-100 text-blue-600';
    if (isRejected) return 'bg-red-100 text-red-600';
    if (isSuggested) return 'bg-yellow-100 text-yellow-700';
    return 'bg-green-100 text-green-600';
  };

  if (isMobile) {
    return (
      <View style={{ flexDirection: 'column', backgroundColor: '#fff', borderRadius: 12, padding: 16, marginBottom: 16, borderWidth: 1, borderColor: '#F3F4F6', shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.05, shadowRadius: 2 }}>
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 12 }}>
          <View style={{ flex: 1 }}>
            <Text style={{ color: '#111827', fontWeight: 'bold', fontSize: 16 }}>{order.po_number}</Text>
            <Text style={{ color: '#6B7280', fontSize: 12 }}>{projectName}</Text>
          </View>
          <View style={{ alignItems: 'flex-end' }}>
            <View className={`px-2 py-1 rounded ${getStatusColor().split(' ')[0]}`}>
              <Text className={`text-[10px] font-bold uppercase ${getStatusColor().split(' ')[1]}`}>{order.status}</Text>
            </View>
          </View>
        </View>
        
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 16 }}>
          <View style={{ flex: 1, paddingRight: 8 }}>
            <Text style={{ color: '#9CA3AF', fontSize: 12, marginBottom: 4 }}>Items</Text>
            <Text style={{ color: '#374151', fontWeight: '600' }} numberOfLines={2}>
              {order.items || `Material ID: ${order.material_id}`}
            </Text>
            {isSuggested && order.supplier_notes && (
              <Text style={{ color: '#CA8A04', fontSize: 11, fontStyle: 'italic', marginTop: 4 }} numberOfLines={1}>Note: {order.supplier_notes}</Text>
            )}
          </View>
          <View style={{ alignItems: 'flex-end', paddingLeft: 8 }}>
            <Text style={{ color: '#9CA3AF', fontSize: 12, marginBottom: 4 }}>Quantity / Cost</Text>
            {isSuggested ? (
               <Text style={{ color: '#9CA3AF', fontSize: 14, fontWeight: '500', textDecorationLine: 'line-through' }}>{order.quantity_ordered}</Text>
            ) : (
               <Text style={{ color: '#111827', fontSize: 14, fontWeight: 'bold' }}>{order.quantity_ordered}</Text>
            )}
            {isSuggested && (
               <Text style={{ color: '#A16207', fontSize: 14, fontWeight: 'bold' }}>{order.suggested_quantity}</Text>
            )}
            <Text style={{ color: '#6B7280', fontSize: 12 }}>Rs. {order.total_price}</Text>
          </View>
        </View>

        <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 16 }}>
          <View>
            <Text style={{ color: '#9CA3AF', fontSize: 12, marginBottom: 4 }}>Expected By</Text>
            {isSuggested ? (
               <Text style={{ color: '#9CA3AF', fontSize: 14, fontWeight: '500', textDecorationLine: 'line-through' }}>{order.expected_date}</Text>
            ) : (
               <Text style={{ color: '#111827', fontSize: 14, fontWeight: 'bold' }}>{order.expected_date}</Text>
            )}
            {isSuggested && (
               <Text style={{ color: '#A16207', fontSize: 14, fontWeight: 'bold' }}>{order.suggested_date}</Text>
            )}
          </View>
        </View>
        
        {isPending ? (
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', gap: 8 }}>
            <Pressable onPress={() => onApprove(order.id)} style={{ flex: 1, backgroundColor: '#22C55E', paddingVertical: 10, borderRadius: 8, alignItems: 'center' }}>
              <Text style={{ color: '#fff', fontSize: 12, fontWeight: 'bold' }}>Approve</Text>
            </Pressable>
            <Pressable onPress={() => onSuggestClick(order)} style={{ flex: 1, backgroundColor: '#EAB308', paddingVertical: 10, borderRadius: 8, alignItems: 'center' }}>
              <Text style={{ color: '#fff', fontSize: 12, fontWeight: 'bold' }}>Suggest</Text>
            </Pressable>
            <Pressable onPress={() => onReject(order.id)} style={{ flex: 1, backgroundColor: '#EF4444', paddingVertical: 10, borderRadius: 8, alignItems: 'center' }}>
              <Text style={{ color: '#fff', fontSize: 12, fontWeight: 'bold' }}>Reject</Text>
            </Pressable>
          </View>
        ) : (
          <View style={{ backgroundColor: '#F3F4F6', paddingVertical: 10, borderRadius: 8, alignItems: 'center' }}>
            <Text style={{ color: '#9CA3AF', fontSize: 12, fontWeight: 'bold' }}>No Action Available</Text>
          </View>
        )}
      </View>
    );
  }

  return (
    <View className="flex-row items-center py-4 border-b border-gray-100">
      <View className="w-[15%] pr-2">
        <Text className="text-brand-text font-bold text-sm truncate" numberOfLines={1}>{order.po_number}</Text>
        <Text className="text-gray-500 text-xs truncate" numberOfLines={1}>{projectName}</Text>
      </View>

      <View className="w-[20%] pr-2">
        <Text className="text-brand-text text-sm" numberOfLines={2}>
          {order.items || `Material ID: ${order.material_id}`}
        </Text>
        {isSuggested && order.supplier_notes && (
          <Text className="text-yellow-600 text-xs italic mt-1" numberOfLines={1}>Note: {order.supplier_notes}</Text>
        )}
      </View>

      <View className="w-[12%]">
        {isSuggested ? (
           <Text className="text-brand-text text-sm font-medium line-through text-gray-400">{order.quantity_ordered}</Text>
        ) : (
           <Text className="text-brand-text text-sm font-medium">{order.quantity_ordered}</Text>
        )}
        {isSuggested && (
           <Text className="text-yellow-700 text-sm font-bold">{order.suggested_quantity}</Text>
        )}
        <Text className="text-gray-400 text-xs truncate">Total: Rs. {order.total_price}</Text>
      </View>

      <View className="w-[12%]">
        {isSuggested ? (
           <Text className="text-brand-text text-sm font-medium line-through text-gray-400">{order.expected_date}</Text>
        ) : (
           <Text className="text-brand-text text-sm font-medium">{order.expected_date}</Text>
        )}
        {isSuggested && (
           <Text className="text-yellow-700 text-sm font-bold">{order.suggested_date}</Text>
        )}
      </View>

      <View className="w-[12%]">
        <View className={`px-2 py-1 rounded self-start ${getStatusColor().split(' ')[0]}`}>
          <Text className={`text-xs font-semibold ${getStatusColor().split(' ')[1]}`}>
            {order.status}
          </Text>
        </View>
      </View>

      <View className="flex-1 flex-row justify-end pl-1">
        {isPending ? (
          <View className="flex-row items-center space-x-1.5">
            <Pressable onPress={() => onApprove(order.id)} className="bg-green-500 px-2 py-1.5 rounded shadow-sm">
              <Text className="text-white text-[11px] font-bold">Approve</Text>
            </Pressable>
            <Pressable onPress={() => onSuggestClick(order)} className="bg-yellow-500 px-2 py-1.5 rounded shadow-sm">
              <Text className="text-white text-[11px] font-bold">Suggest</Text>
            </Pressable>
            <Pressable onPress={() => onReject(order.id)} className="bg-red-500 px-2 py-1.5 rounded shadow-sm">
              <Text className="text-white text-[11px] font-bold">Reject</Text>
            </Pressable>
          </View>
        ) : (
          <Text className="text-gray-400 text-xs text-right pr-2">No Action</Text>
        )}
      </View>
    </View>
  );
};


export const SupplierOrdersTable = ({ refreshTrigger = 0, onOrderAction }: { refreshTrigger?: number, onOrderAction: () => void }) => {
  const { isMobile } = useResponsive();
  const { user } = useAuth();
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  
  const [suggestModalVisible, setSuggestModalVisible] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<any>(null);

  useEffect(() => {
    let isMounted = true;
    
    const loadOrders = async () => {
      try {
        const { data: sessionData } = await supabase.auth.getSession();
        if (!sessionData?.session || !user) {
          if (isMounted) setLoading(false);
          return;
        }

        const { data, error } = await supabase
          .from('purchase_orders')
          .select(`
            id, po_number, items, material_id, quantity_ordered, total_price, expected_date, status,
            suggested_quantity, suggested_date, supplier_notes,
            projects!inner(name)
          `)
          .eq('supplier_id', user.id)
          .in('status', ['Pending Delivery', 'Confirmed', 'Rejected', 'Suggested'])
          .order('created_at', { ascending: false });

        if (error) throw error;
        
        if (isMounted) setOrders(data || []);
      } catch (error) {
        console.warn('Failed to load supplier orders:', error);
      } finally {
        if (isMounted) setLoading(false);
      }
    };
    
    loadOrders();
    
    return () => { isMounted = false; };
  }, [refreshTrigger, user]);

  const handleApprove = async (id: string) => {
    try {
      setLoading(true);
      await api.purchaseOrders.approve(id);
      onOrderAction();
    } catch (e: any) {
      Alert.alert('Error', 'Failed to approve order');
      setLoading(false);
    }
  };

  const handleReject = async (id: string) => {
    try {
      setLoading(true);
      await api.purchaseOrders.reject(id);
      onOrderAction();
    } catch (e: any) {
      Alert.alert('Error', 'Failed to reject order');
      setLoading(false);
    }
  };

  const handleSuggestSubmit = async (id: string, qty: number, date: string, notes: string) => {
    try {
      setLoading(true);
      setSuggestModalVisible(false);
      await api.purchaseOrders.suggest(id, {
        suggested_quantity: qty,
        suggested_date: date,
        supplier_notes: notes
      });
      onOrderAction();
    } catch (e: any) {
      Alert.alert('Error', 'Failed to submit suggestion');
      setLoading(false);
    }
  };

  return (
    <View className="bg-white rounded-lg p-6 shadow-sm border border-gray-100 flex-1 min-h-[500px]">
      <View className="mb-6">
        <Text className="text-lg font-bold text-brand-text mb-1">Incoming Purchase Orders</Text>
        <Text className="text-brand-text-muted text-xs">Manage and approve material requests</Text>
      </View>

      {!isMobile && (
        <View className="flex-row py-3 border-b border-gray-200 pr-2">
          <Text className="w-[15%] text-xs font-semibold text-gray-500 uppercase">PO / Project</Text>
          <Text className="w-[20%] text-xs font-semibold text-gray-500 uppercase">Items</Text>
          <Text className="w-[12%] text-xs font-semibold text-gray-500 uppercase">Quantity / Cost</Text>
          <Text className="w-[12%] text-xs font-semibold text-gray-500 uppercase">Expected By</Text>
          <Text className="w-[12%] text-xs font-semibold text-gray-500 uppercase">Status</Text>
          <Text className="flex-1 text-xs font-semibold text-gray-500 uppercase text-right">Action</Text>
        </View>
      )}

      <ScrollView showsVerticalScrollIndicator={false} className="flex-1">
        {loading ? (
          <View className="py-10 items-center justify-center">
            <ActivityIndicator color="#F97316" />
          </View>
        ) : orders.length === 0 ? (
          <View className="py-10 items-center justify-center">
            <Text className="text-gray-400">No active purchase orders found.</Text>
          </View>
        ) : (
          orders.map(order => (
            <OrderRow 
              key={order.id}
              order={order} 
              isMobile={isMobile}
              onApprove={handleApprove}
              onReject={handleReject}
              onSuggestClick={(o: any) => { setSelectedOrder(o); setSuggestModalVisible(true); }}
            />
          ))
        )}
      </ScrollView>

      <SuggestModal 
        visible={suggestModalVisible}
        order={selectedOrder}
        onClose={() => setSuggestModalVisible(false)}
        onSubmit={handleSuggestSubmit}
      />
    </View>
  );
};

import React, { createContext, useContext, useEffect, useState } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { Platform } from 'react-native';
import { useColorScheme } from 'nativewind';

type ThemeContextType = {
  isDark: boolean;
  toggleTheme: () => void;
};

const ThemeContext = createContext<ThemeContextType>({
  isDark: false,
  toggleTheme: () => {},
});

const THEME_KEY = '@cf_theme';

export const ThemeProvider = ({ children }: { children: React.ReactNode }) => {
  const [isDark, setIsDark] = useState(false);
  const { setColorScheme } = useColorScheme();

  // Load saved preference on mount
  useEffect(() => {
    AsyncStorage.getItem(THEME_KEY).then((val) => {
      const dark = val === 'dark';
      setIsDark(dark);
      setColorScheme(dark ? 'dark' : 'light');
      applyTheme(dark);
    });
  }, []);

  const applyTheme = (dark: boolean) => {
    if (Platform.OS === 'web') {
      try {
        const root = document.documentElement;
        if (dark) {
          root.classList.add('dark');
        } else {
          root.classList.remove('dark');
        }
      } catch {}
    }
  };

  const toggleTheme = () => {
    const next = !isDark;
    setIsDark(next);
    setColorScheme(next ? 'dark' : 'light');
    applyTheme(next);
    AsyncStorage.setItem(THEME_KEY, next ? 'dark' : 'light');
  };

  return (
    <ThemeContext.Provider value={{ isDark, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => useContext(ThemeContext);

import { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';
import { Alert } from 'react-native';

export function useNotifications(userId: string | null, role: string | null) {
  const [notifications, setNotifications] = useState<any[]>([]);
  const [badgeCount, setBadgeCount] = useState(0);

  useEffect(() => {
    if (!userId || !role) return;

    // Initial fetch
    supabase
      .from('notifications')
      .select('*')
      .or(`user_id.eq.${userId},target_role.eq.All,target_role.eq.${role}`)
      .order('created_at', { ascending: false })
      .then(({ data }) => {
        if (data) {
          setNotifications(data);
          setBadgeCount(data.filter(n => !n.is_read).length);
        }
      });

    // Subscriptions
    const userSub = supabase.channel('user-notifs')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'notifications', filter: `user_id=eq.${userId}` }, handleNewNotification)
      .subscribe();

    const roleSub = supabase.channel('role-notifs')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'notifications', filter: `target_role=eq.${role}` }, handleNewNotification)
      .subscribe();

    const allSub = supabase.channel('all-notifs')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'notifications', filter: `target_role=eq.All` }, handleNewNotification)
      .subscribe();

    function handleNewNotification(payload: any) {
      setNotifications(prev => [payload.new, ...prev]);
      setBadgeCount(prev => prev + 1);
      Alert.alert(payload.new.title, payload.new.message);
    }

    return () => {
      supabase.removeChannel(userSub);
      supabase.removeChannel(roleSub);
      supabase.removeChannel(allSub);
    };
  }, [userId, role]);

  const markAllRead = async () => {
    // Optimistic UI
    setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
    setBadgeCount(0);
  };

  return { notifications, badgeCount, markAllRead };
}

export function useAttendance() {
  const [attendance, setAttendance] = useState<any[]>([]);
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  useEffect(() => {
    const sub = supabase.channel('attendance-changes')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'attendance' }, () => setRefreshTrigger(prev => prev + 1))
      .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'attendance' }, () => setRefreshTrigger(prev => prev + 1))
      .subscribe();

    return () => { supabase.removeChannel(sub); };
  }, []);

  const refresh = () => setRefreshTrigger(prev => prev + 1);
  return { attendance, refresh, refreshTrigger };
}

export function usePurchaseOrders(supplierId: string | null) {
  const [orders, setOrders] = useState<any[]>([]);
  const [refreshTrigger, setRefreshTrigger] = useState(0);

  useEffect(() => {
    if (!supplierId) return;

    const sub = supabase.channel('po-changes')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'purchase_orders', filter: `supplier_id=eq.${supplierId}` }, (payload) => {
        setOrders(prev => [payload.new, ...prev]);
        Alert.alert("New Order", `PO ${payload.new.po_number} received.`);
      })
      .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'purchase_orders', filter: `supplier_id=eq.${supplierId}` }, (payload) => {
        setOrders(prev => prev.map(o => o.id === payload.new.id ? payload.new : o));
      })
      .subscribe();

    return () => { supabase.removeChannel(sub); };
  }, [supplierId]);

  const refresh = () => setRefreshTrigger(prev => prev + 1);
  return { orders, refresh, refreshTrigger };
}

